screenPanels.initJs:
function(container, apiUrl, tables) {
  // フォーム要素の取得
  const loginForm = container.querySelector('#login-form');
  const userIdInput = container.querySelector('#user-id');
  const passwordInput = container.querySelector('#password');
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const rememberMeCheckbox = container.querySelector('#remember-me');
  const loginButton = container.querySelector('#login-button');
  const errorMessage = container.querySelector('#error-message');
  const navigationButtons = container.querySelector('#navigation-buttons');

  // パスワード表示/非表示切替
  togglePasswordBtn.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePasswordBtn.textContent = isPassword ? '🙈' : '👁';
  });

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
  }

  // エラーメッセージ非表示関数
  function hideError() {
    errorMessage.style.display = 'none';
  }

  // ログイン処理
  async function handleLogin(userId, password, rememberMe) {
    try {
      // ユーザーテーブルからユーザー情報を取得
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (!users) {
        showError('システムエラーが発生しました。管理者にお問い合わせください。');
        return false;
      }

      // ユーザー認証（実際の実装では暗号化されたパスワードと比較）
      const user = users.find(u => 
        u.ユーザー名 === userId && 
        u.アクティブフラグ === true
      );

      if (!user) {
        showError('ユーザーIDまたはパスワードが正しくありません。');
        return false;
      }

      // 簡易パスワード検証（実際の実装ではハッシュ化されたパスワードと比較）
      if (password.length < 4) {
        showError('ユーザーIDまたはパスワードが正しくありません。');
        return false;
      }

      // ログイン成功時の処理
      hideError();

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ログイン状態を保持する場合はlocalStorageに保存
      if (rememberMe) {
        localStorage.setItem('loginUser', JSON.stringify({
          userId: user.ユーザーID,
          userName: user.ユーザー名,
          displayName: user.氏名,
          loginTime: new Date().toISOString()
        }));
      }

      return true;
    } catch (error) {
      console.error('Login error:', error);
      showError('ログイン処理中にエラーが発生しました。');
      return false;
    }
  }

  // フォーム送信処理
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    const userId = userIdInput.value.trim();
    const password = passwordInput.value;
    const rememberMe = rememberMeCheckbox.checked;

    // 入力値検証
    if (!userId) {
      showError('ユーザーIDを入力してください。');
      userIdInput.focus();
      return;
    }

    if (!password) {
      showError('パスワードを入力してください。');
      passwordInput.focus();
      return;
    }

    // ログインボタンを無効化
    loginButton.disabled = true;
    loginButton.textContent = 'ログイン中...';

    try {
      const loginSuccess = await handleLogin(userId, password, rememberMe);

      if (loginSuccess) {
        // ログインフォームを非表示にし、ナビゲーションボタンを表示
        loginForm.style.display = 'none';
        navigationButtons.style.display = 'block';
      }
    } finally {
      // ログインボタンを有効化
      loginButton.disabled = false;
      loginButton.textContent = 'ログイン';
    }
  });

  // パスワードリセットリンク
  container.querySelector('#forgot-password').addEventListener('click', (e) => {
    e.preventDefault();
    alert('パスワードリセット機能は管理者にお問い合わせください。\n\n連絡先: system-admin@company.com');
  });

  // 画面遷移ボタンのイベントリスナー
  container.querySelector('#nav-register').addEventListener('click', () => {
    window.showScreen("scr-1779345924072"); // 申請書類登録・自動判別画面
  });

  container.querySelector('#nav-monitor').addEventListener('click', () => {
    window.showScreen("scr-1779345940460"); // 承認フロー進捗監視画面
  });

  container.querySelector('#nav-route-config').addEventListener('click', () => {
    window.showScreen("scr-1779349282024"); // 承認ルート設定画面
  });

  // ナビゲーションボタンのホバー効果
  const navButtons = container.querySelectorAll('#navigation-buttons button');
  navButtons.forEach(btn => {
    btn.addEventListener('mouseenter', () => {
      if (btn.style.background === 'var(--primary)') {
        btn.style.background = 'var(--primary-hover)';
      } else {
        btn.style.background = 'rgba(255,255,255,0.05)';
      }
    });

    btn.addEventListener('mouseleave', () => {
      if (btn.id === 'nav-register') {
        btn.style.background = 'var(--primary)';
      } else {
        btn.style.background = 'transparent';
      }
    });
  });

  // ログインボタンのホバー効果
  loginButton.addEventListener('mouseenter', () => {
    if (!loginButton.disabled) {
      loginButton.style.background = 'var(--primary-hover)';
    }
  });

  loginButton.addEventListener('mouseleave', () => {
    if (!loginButton.disabled) {
      loginButton.style.background = 'var(--primary)';
    }
  });

  // 保存されたログイン状態をチェック
  const savedLogin = localStorage.getItem('loginUser');
  if (savedLogin) {
    try {
      const loginData = JSON.parse(savedLogin);
      const loginTime = new Date(loginData.loginTime);
      const now = new Date();
      const hoursDiff = (now - loginTime) / (1000 * 60 * 60);

      // 24時間以内なら自動ログイン状態を提示
      if (hoursDiff < 24) {
        userIdInput.value = loginData.userName || '';
        rememberMeCheckbox.checked = true;

        // 自動ログイン確認メッセージ
        const autoLoginMsg = container.createElement('div');
        autoLoginMsg.style.cssText = 'background: rgba(34, 197, 94, 0.1); border: 1px solid rgba(34, 197, 94, 0.3); border-radius: 6px; padding: 8px 12px; margin-bottom: 16px; color: #22c55e; font-size: 13px;';
        autoLoginMsg.textContent = `前回のログイン状態が保持されています (${loginData.displayName || loginData.userName})`;
        container.querySelector('.login-card').insertBefore(autoLoginMsg, loginForm);
      }
    } catch (error) {
      localStorage.removeItem('loginUser');
    }
  }

  // 初期フォーカス
  userIdInput.focus();
}

function(container, apiUrl, tables) {
  // DOM要素の取得
  const uploadArea = container.querySelector('#upload-area');
  const fileInput = container.querySelector('#file-input');
  const uploadProgress = container.querySelector('#upload-progress');
  const uploadFilename = container.querySelector('#upload-filename');
  const uploadPercent = container.querySelector('#upload-percent');
  const progressBar = container.querySelector('#progress-bar');
  const detectionResult = container.querySelector('#detection-result');
  const detectedType = container.querySelector('#detected-type');
  const confidenceBar = container.querySelector('#confidence-fill');
  const confidenceText = container.querySelector('#confidence-text');
  const manualDocType = container.querySelector('#manual-doc-type');
  const flowSteps = container.querySelector('#flow-steps');
  const documentPreview = container.querySelector('#document-preview');
  const approverList = container.querySelector('#approver-list');
  const approvers = container.querySelector('#approvers');
  const applicationTitle = container.querySelector('#application-title');
  const urgencyLevel = container.querySelector('#urgency-level');
  const applicationContent = container.querySelector('#application-content');

  // 文書種別マスタデータ
  const docTypes = {
    'vacation': { name: '休暇申請', steps: ['直属上司', '人事部長'] },
    'expense': { name: '経費申請', steps: ['直属上司', '経理部長'] },
    'purchase': { name: '購買申請', steps: ['直属上司', '購買部長', '役員'] },
    'approval': { name: '稟議書', steps: ['部長', '役員', '社長'] },
    'contract': { name: '契約書', steps: ['法務部長', '役員', '社長'] }
  };

  // ファイルアップロード処理
  function handleFileUpload(file) {
    if (!file) return;

    // 対応形式チェック
    const allowedTypes = ['.pdf', '.docx', '.xlsx', '.pptx'];
    const fileExt = '.' + file.name.split('.').pop().toLowerCase();
    if (!allowedTypes.includes(fileExt)) {
      alert('対応していないファイル形式です。PDF、Word、Excel、PowerPointファイルを選択してください。');
      return;
    }

    // プログレス表示開始
    uploadFilename.textContent = file.name;
    uploadProgress.style.display = 'block';

    // プログレス更新のシミュレーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 20;
      if (progress >= 100) {
        progress = 100;
        clearInterval(progressInterval);

        // アップロード完了後の処理
        setTimeout(() => {
          performDocumentAnalysis(file);
        }, 500);
      }

      progressBar.style.width = progress + '%';
      uploadPercent.textContent = Math.round(progress) + '%';
    }, 200);

    // プレビュー更新
    updateDocumentPreview(file);
  }

  // 文書解析・自動判別
  function performDocumentAnalysis(file) {
    // 簡易的な自動判別ロジック（実際はAI判定）
    const filename = file.name.toLowerCase();
    let detectedTypeKey = 'approval';
    let confidence = 75;

    if (filename.includes('休暇') || filename.includes('vacation')) {
      detectedTypeKey = 'vacation';
      confidence = 92;
    } else if (filename.includes('経費') || filename.includes('expense')) {
      detectedTypeKey = 'expense';
      confidence = 88;
    } else if (filename.includes('購買') || filename.includes('purchase')) {
      detectedTypeKey = 'purchase';
      confidence = 85;
    } else if (filename.includes('契約') || filename.includes('contract')) {
      detectedTypeKey = 'contract';
      confidence = 90;
    }

    // 判別結果表示
    detectionResult.style.display = 'block';
    detectedType.textContent = docTypes[detectedTypeKey].name;
    confidenceBar.style.width = confidence + '%';
    confidenceText.textContent = confidence + '%';

    // 信頼度による色分け
    if (confidence >= 80) {
      confidenceBar.style.background = '#22c55e';
    } else if (confidence >= 60) {
      confidenceBar.style.background = '#f59e0b';
    } else {
      confidenceBar.style.background = '#ef4444';
    }

    // 承認フロー設定
    updateApprovalFlow(detectedTypeKey);
  }

  // 承認フロー更新
  function updateApprovalFlow(typeKey) {
    const docType = docTypes[typeKey];
    if (!docType) return;

    flowSteps.textContent = docType.steps.join(' → ');

    // 承認者一覧表示
    approverList.style.display = 'block';
    approvers.innerHTML = docType.steps.map((step, index) => 
      `<div style="display: flex; align-items: center; gap: 8px; margin-bottom: 6px;">
        <span style="width: 20px; height: 20px; background: var(--primary); color: #fff; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 600;">${index + 1}</span>
        <span style="color: var(--text);">${step}</span>
      </div>`
    ).join('');
  }

  // 文書プレビュー更新
  function updateDocumentPreview(file) {
    const fileExt = '.' + file.name.split('.').pop().toLowerCase();
    let icon = '📄';

    switch (fileExt) {
      case '.pdf': icon = '📕'; break;
      case '.docx': icon = '📘'; break;
      case '.xlsx': icon = '📗'; break;
      case '.pptx': icon = '📙'; break;
    }

    documentPreview.innerHTML = `
      <div style="text-align: center;">
        <div style="font-size: 48px; margin-bottom: 8px;">${icon}</div>
        <div style="font-size: 12px; color: var(--text); font-weight: 500; margin-bottom: 4px;">${file.name}</div>
        <div style="font-size: 11px; color: var(--text-muted);">${(file.size / 1024).toFixed(1)} KB</div>
      </div>
    `;
  }

  // ドラッグ&ドロップイベント
  uploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'var(--primary)';
    uploadArea.style.background = 'rgba(255,255,255,0.05)';
  });

  uploadArea.addEventListener('dragleave', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    uploadArea.style.background = 'rgba(0,0,0,0.15)';
  });

  uploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    uploadArea.style.background = 'rgba(0,0,0,0.15)';

    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFileUpload(files[0]);
    }
  });

  uploadArea.addEventListener('click', () => {
    fileInput.click();
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFileUpload(e.target.files[0]);
    }
  });

  // 手動文書種別選択
  manualDocType.addEventListener('change', (e) => {
    if (e.target.value) {
      updateApprovalFlow(e.target.value);
    }
  });

  // ボタンイベント
  container.querySelector('#btn-clear').addEventListener('click', () => {
    if (confirm('入力内容をクリアしますか？')) {
      fileInput.value = '';
      applicationTitle.value = '';
      applicationContent.value = '';
      urgencyLevel.value = 'normal';
      manualDocType.value = '';
      uploadProgress.style.display = 'none';
      detectionResult.style.display = 'none';
      approverList.style.display = 'none';
      documentPreview.innerHTML = 'ファイルを選択してください';
    }
  });

  container.querySelector('#btn-save-draft').addEventListener('click', async () => {
    const data = {
      申請者ID: 'current-user-id',
      申請種別: manualDocType.value || 'approval',
      申請タイトル: applicationTitle.value || '無題の申請',
      申請内容: applicationContent.value || '',
      承認状態: '下書き',
      承認段階: 0,
      緊急フラグ: urgencyLevel.value !== 'normal',
      添付ファイル有無: !!fileInput.files.length,
      作成者ID: 'current-user-id',
      更新者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, data);
    if (saved) {
      alert('下書きを保存しました');
    }
  });

  container.querySelector('#btn-submit').addEventListener('click', async () => {
    if (!applicationTitle.value.trim()) {
      alert('申請タイトルを入力してください');
      return;
    }

    if (!fileInput.files.length) {
      alert('申請書類ファイルを選択してください');
      return;
    }

    const data = {
      申請者ID: 'current-user-id',
      申請種別: manualDocType.value || 'approval',
      申請タイトル: applicationTitle.value,
      申請内容: applicationContent.value || '',
      承認状態: '申請中',
      承認段階: 1,
      緊急フラグ: urgencyLevel.value !== 'normal',
      添付ファイル有無: true,
      作成者ID: 'current-user-id',
      更新者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, data);
    if (saved) {
      alert('申請を提出しました');
      // フォームクリア
      container.querySelector('#btn-clear').click();
    }
  });

  // クイックアクションボタン
  container.querySelector('#btn-new-application').addEventListener('click', () => {
    window.showScreen("scr-1779346840879");
  });

  container.querySelector('#btn-digitization-check').addEventListener('click', () => {
    window.showScreen("scr-1779350034604");
  });
}

function(container, apiUrl, tables) {
  let currentDocumentId = null;

  // 承認履歴テーブル再描画
  function renderApprovalHistory(histories) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = histories.map(h => `
      <tr data-id="${h.id || ''}">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${h.承認者名 || h.承認者ID || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">
          <span style="padding: 2px 6px; border-radius: 3px; font-size: 11px; ${getStatusStyle(h.承認結果 || h.結果)}">${h.承認結果 || h.結果 || ''}</span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${h.承認コメント || h.コメント || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text-muted); border-bottom: 1px solid rgba(255,255,255,0.05);">${formatDateTime(h.承認日時 || h.処理日時)}</td>
      </tr>
    `).join("");
  }

  function getStatusStyle(status) {
    switch(status) {
      case '承認': case '承認済': return 'background: rgba(34,197,94,0.2); color: #22c55e;';
      case '差戻し': return 'background: rgba(249,115,22,0.2); color: #f97316;';
      case '却下': case '否認': return 'background: rgba(239,68,68,0.2); color: #ef4444;';
      case '保留': return 'background: rgba(156,163,175,0.2); color: #9ca3af;';
      default: return 'background: rgba(59,130,246,0.2); color: #3b82f6;';
    }
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP') + ' ' + date.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});
  }

  // 申請書類詳細表示
  function displayDocumentDetails(doc) {
    if (!doc) return;

    container.querySelector("#doc-id").textContent = doc.id || doc.申請書類ID || '';
    container.querySelector("#doc-applicant").textContent = doc.申請者名 || doc.申請者ID || '';
    container.querySelector("#doc-type").textContent = doc.申請種別 || '';
    container.querySelector("#doc-date").textContent = formatDateTime(doc.作成日時);
    container.querySelector("#doc-title").textContent = doc.申請タイトル || '';
    container.querySelector("#doc-content").textContent = doc.申請内容 || '';

    // ステータス表示
    const statusBadge = container.querySelector("#status-badge");
    const currentStep = container.querySelector("#current-step");
    statusBadge.textContent = doc.承認状態 || '申請中';
    statusBadge.style.cssText = `padding: 3px 8px; border-radius: 4px; font-size: 11px; font-weight: 500; ${getStatusStyle(doc.承認状態)}`;
    currentStep.textContent = `${doc.承認段階 || 1}次承認待ち`;

    // 現在の承認者
    container.querySelector("#current-approver").textContent = doc.現在承認者名 || doc.現在承認者ID || '-';

    currentDocumentId = doc.id || doc.申請書類ID;
  }

  // 承認フロー表示
  function displayApprovalFlow(steps) {
    const flowContainer = container.querySelector("#approval-flow");
    flowContainer.innerHTML = steps.map((step, index) => `
      <div style="display: flex; align-items: center; gap: 4px;">
        <div style="padding: 4px 8px; border-radius: 4px; font-size: 11px; ${step.完了 ? 'background: rgba(34,197,94,0.2); color: #22c55e;' : step.現在 ? 'background: rgba(249,115,22,0.2); color: #f97316;' : 'background: rgba(156,163,175,0.2); color: #9ca3af;'}">
          ${step.承認者名 || step.承認者ID}
        </div>
        ${index < steps.length - 1 ? '<span style="color: var(--text-muted);">→</span>' : ''}
      </div>
    `).join("");
  }

  // 初期データ表示
  if (tables[1] && tables[1].records && tables[1].records.length > 0) {
    displayDocumentDetails(tables[1].records[0]);
  }

  // 承認履歴初期表示
  if (tables[6] && tables[6].records) {
    renderApprovalHistory(tables[6].records);
  }

  // 承認ステップ初期表示（フロー表示用）
  if (tables[4] && tables[4].records) {
    const steps = tables[4].records.map((step, index) => ({
      ...step,
      現在: index === 0, // 仮で最初のステップを現在とする
      完了: false
    }));
    displayApprovalFlow(steps);
  }

  // 承認ボタン
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    if (!currentDocumentId) {
      alert("処理対象の申請書類が選択されていません");
      return;
    }

    const comment = container.querySelector("#approval-comment").value;

    if (!confirm("この申請を承認しますか？")) return;

    // 承認履歴に記録
    const historyData = {
      申請書類ID: currentDocumentId,
      承認者ID: 'current-user', // 実際は現在のユーザーID
      承認結果: '承認',
      承認コメント: comment,
      承認日時: new Date().toISOString(),
      処理順序: 1
    };

    const saved = await window.aivicApi.save(6, historyData);
    if (saved) {
      // 申請書類のステータス更新
      await window.aivicApi.update(1, currentDocumentId, {
        承認状態: '承認済',
        最終承認日時: new Date().toISOString()
      });

      alert("承認処理が完了しました");
      container.querySelector("#approval-comment").value = '';

      // 履歴再読み込み
      const histories = await window.aivicApi.list(6);
      if (histories) renderApprovalHistory(histories);
    }
  });

  // 差戻しボタン
  container.querySelector("#btn-reject").addEventListener("click", async () => {
    if (!currentDocumentId) {
      alert("処理対象の申請書類が選択されていません");
      return;
    }

    const comment = container.querySelector("#approval-comment").value;
    if (!comment.trim()) {
      alert("差戻し理由を入力してください");
      return;
    }

    if (!confirm("この申請を差戻しますか？")) return;

    const historyData = {
      申請書類ID: currentDocumentId,
      承認者ID: 'current-user',
      承認結果: '差戻し',
      承認コメント: comment,
      承認日時: new Date().toISOString(),
      処理順序: 1
    };

    const saved = await window.aivicApi.save(6, historyData);
    if (saved) {
      await window.aivicApi.update(1, currentDocumentId, {
        承認状態: '差戻し'
      });

      alert("差戻し処理が完了しました");
      container.querySelector("#approval-comment").value = '';

      const histories = await window.aivicApi.list(6);
      if (histories) renderApprovalHistory(histories);
    }
  });

  // 却下ボタン
  container.querySelector("#btn-deny").addEventListener("click", async () => {
    if (!currentDocumentId) {
      alert("処理対象の申請書類が選択されていません");
      return;
    }

    const comment = container.querySelector("#approval-comment").value;
    if (!comment.trim()) {
      alert("却下理由を入力してください");
      return;
    }

    if (!confirm("この申請を却下しますか？")) return;

    const historyData = {
      申請書類ID: currentDocumentId,
      承認者ID: 'current-user',
      承認結果: '却下',
      承認コメント: comment,
      承認日時: new Date().toISOString(),
      処理順序: 1
    };

    const saved = await window.aivicApi.save(6, historyData);
    if (saved) {
      await window.aivicApi.update(1, currentDocumentId, {
        承認状態: '却下',
        却下理由: comment
      });

      alert("却下処理が完了しました");
      container.querySelector("#approval-comment").value = '';

      const histories = await window.aivicApi.list(6);
      if (histories) renderApprovalHistory(histories);
    }
  });

  // 承認者追加ボタン
  container.querySelector("#btn-add-approver").addEventListener("click", async () => {
    const newApprover = container.querySelector("#new-approver-select").value;
    const position = container.querySelector("#insert-position").value;
    const reason = container.querySelector("#route-change-reason").value;

    if (!newApprover || !position) {
      alert("承認者と挿入位置を選択してください");
      return;
    }

    if (!reason.trim()) {
      alert("変更理由を入力してください");
      return;
    }

    if (!confirm("承認者を追加しますか？")) return;

    // 処理ルート変更履歴に記録
    const changeData = {
      申請書類ID: currentDocumentId,
      変更種別: 'ステップ追加',
      変更理由: reason,
      変更内容: `承認者追加: ${newApprover} (${position})`,
      変更実行者ID: 'current-user',
      変更日時: new Date().toISOString(),
      有効フラグ: true
    };

    const saved = await window.aivicApi.save(10, changeData);
    if (saved) {
      alert("承認者が追加されました");
      container.querySelector("#new-approver-select").value = '';
      container.querySelector("#insert-position").value = '';
      container.querySelector("#route-change-reason").value = '';
    }
  });

  // 承認者削除ボタン
  container.querySelector("#btn-remove-approver").addEventListener("click", async () => {
    const reason = container.querySelector("#route-change-reason").value;

    if (!reason.trim()) {
      alert("変更理由を入力してください");
      return;
    }

    if (!confirm("現在の承認者を削除しますか？")) return;

    const changeData = {
      申請書類ID: currentDocumentId,
      変更種別: 'ステップ削除',
      変更理由: reason,
      変更内容: '現在の承認者を削除',
      変更実行者ID: 'current-user',
      変更日時: new Date().toISOString(),
      有効フラグ: true
    };

    const saved = await window.aivicApi.save(10, changeData);
    if (saved) {
      alert("承認者が削除されました");
      container.querySelector("#route-change-reason").value = '';
    }
  });

  // 処理ルート更新ボタン（画面遷移）
  container.querySelector("#btn-update-route").addEventListener("click", () => {
    window.showScreen("scr-1779350057855");
  });
}

function(container, apiUrl, tables) {
  // テーブル再描画関数
  function renderDelayRows(rows) {
    const tbody = container.querySelector("#tbody-delay-list");
    tbody.innerHTML = rows.map(r => {
      const delayHours = Math.floor((new Date() - new Date(r.作成日時)) / (1000 * 60 * 60));
      const statusColor = delayHours > 72 ? '#dc267f' : delayHours > 24 ? '#ff6a00' : '#28a745';
      const statusText = delayHours > 72 ? 'エラー' : delayHours > 24 ? '警告' : '正常';

      return `<tr data-id="${r.申請書類ID || r.id}">
        <td>${r.申請書類ID || r.id || ""}</td>
        <td>${r.申請者名 || ""}</td>
        <td>${r.申請種別 || ""}</td>
        <td>${r.申請タイトル || ""}</td>
        <td>${r.現在承認者名 || ""}</td>
        <td>${delayHours}時間</td>
        <td><span style="color: ${statusColor}; font-weight: 500;">${statusText}</span></td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.申請書類ID || r.id}">詳細</button>
          <button class="action-btn secondary remind-btn" data-id="${r.申請書類ID || r.id}">催促</button>
        </td>
      </tr>`;
    }).join("");
  }

  function renderNotificationRows(rows) {
    const tbody = container.querySelector("#tbody-notification-history");
    tbody.innerHTML = rows.map(r => `<tr data-id="${r.通知履歴ID || r.id}">
      <td>${r.送信日時 ? new Date(r.送信日時).toLocaleString() : ""}</td>
      <td>${r.通知種別 || ""}</td>
      <td>${r.通知先ユーザー名 || ""}</td>
      <td>${r.申請書類ID || ""}</td>
      <td><span style="color: ${r.送信状態 === '送信完了' ? '#28a745' : '#dc267f'};">${r.送信状態 || ""}</span></td>
      <td><span style="color: ${r.既読フラグ ? '#28a745' : '#6c757d'};">${r.既読フラグ ? '既読' : '未読'}</span></td>
    </tr>`).join("");
  }

  // 初期データ描画
  renderDelayRows(tables[1]?.records || []);
  renderNotificationRows(tables[6]?.records || []);

  // 遅延検知設定保存
  container.querySelector("#btn-save-delay-setting").addEventListener("click", async () => {
    const documentType = container.querySelector("#select-document-type").value;
    const warningThreshold = container.querySelector("#input-warning-threshold").value;
    const errorThreshold = container.querySelector("#input-error-threshold").value;
    const notificationMethod = container.querySelector("#select-notification-method").value;
    const businessDays = container.querySelector("#checkbox-business-days").checked;

    if (!documentType || !warningThreshold || !errorThreshold || !notificationMethod) {
      alert("必須項目を入力してください");
      return;
    }

    const saved = await window.aivicApi.save(10, {
      文書種別ID: documentType,
      設定名: `${documentType}遅延検知設定`,
      警告閾値時間: parseInt(warningThreshold),
      エラー閾値時間: parseInt(errorThreshold),
      営業日計算フラグ: businessDays,
      通知方法: notificationMethod,
      有効フラグ: true,
      作成者ID: "current-user",
      更新者ID: "current-user"
    });

    if (saved) {
      alert("設定を保存しました");
      // フォームクリア
      container.querySelector("#select-document-type").value = "";
      container.querySelector("#input-warning-threshold").value = "";
      container.querySelector("#input-error-threshold").value = "";
      container.querySelector("#select-notification-method").value = "";
      container.querySelector("#checkbox-business-days").checked = false;
    }
  });

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const keyword = container.querySelector("#input-search").value;
    const rows = await window.aivicApi.list(1);
    if (rows) {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
      );
      renderDelayRows(filtered);
    }
  });

  // 通知履歴絞り込み
  container.querySelector("#btn-filter-notifications").addEventListener("click", async () => {
    const filter = container.querySelector("#select-notification-filter").value;
    const rows = await window.aivicApi.list(6);
    if (rows) {
      const filtered = filter ? rows.filter(r => r.通知種別 === filter) : rows;
      renderNotificationRows(filtered);
    }
  });

  // CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(1);
    if (rows) {
      const headers = ["申請ID", "申請者", "文書種別", "申請タイトル", "現在承認者", "遅延時間", "状態"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(r => {
          const delayHours = Math.floor((new Date() - new Date(r.作成日時)) / (1000 * 60 * 60));
          const statusText = delayHours > 72 ? 'エラー' : delayHours > 24 ? '警告' : '正常';
          return [
            r.申請書類ID || r.id || "",
            r.申請者名 || "",
            r.申請種別 || "",
            r.申請タイトル || "",
            r.現在承認者名 || "",
            `${delayHours}時間`,
            statusText
          ].map(field => `"${field}"`).join(",");
        })
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "delay_cases.csv";
      link.click();
    }
  });

  // モーダル制御
  const modal = container.querySelector("#modal-case-detail");
  const closeModal = () => modal.style.display = "none";

  container.querySelector("#btn-close-modal").addEventListener("click", closeModal);
  container.querySelector("#btn-cancel-modal").addEventListener("click", closeModal);

  // 行レベル操作
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const remindBtn = e.target.closest(".remind-btn");

    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const rows = await window.aivicApi.list(1);
      const record = rows?.find(r => (r.申請書類ID || r.id) === id);

      if (record) {
        const modalContent = container.querySelector("#modal-content");
        modalContent.innerHTML = `
          <div style="display: grid; grid-template-columns: 120px 1fr; gap: 8px; margin-bottom: 12px;">
            <div style="font-weight: 500;">申請ID:</div>
            <div>${record.申請書類ID || record.id || ""}</div>
            <div style="font-weight: 500;">申請者:</div>
            <div>${record.申請者名 || ""}</div>
            <div style="font-weight: 500;">申請種別:</div>
            <div>${record.申請種別 || ""}</div>
            <div style="font-weight: 500;">申請タイトル:</div>
            <div>${record.申請タイトル || ""}</div>
            <div style="font-weight: 500;">申請内容:</div>
            <div>${record.申請内容 || ""}</div>
            <div style="font-weight: 500;">現在承認者:</div>
            <div>${record.現在承認者名 || ""}</div>
            <div style="font-weight: 500;">承認状態:</div>
            <div>${record.承認状態 || ""}</div>
            <div style="font-weight: 500;">作成日時:</div>
            <div>${record.作成日時 ? new Date(record.作成日時).toLocaleString() : ""}</div>
          </div>
        `;
        modal.style.display = "block";
      }
    }

    if (remindBtn) {
      window.showScreen("scr-1779349608362");
    }
  });

  // ダッシュボード更新
  const updateDashboard = async () => {
    const rows = await window.aivicApi.list(1);
    if (rows) {
      let warningCount = 0;
      let errorCount = 0;

      rows.forEach(r => {
        const delayHours = Math.floor((new Date() - new Date(r.作成日時)) / (1000 * 60 * 60));
        if (delayHours > 72) errorCount++;
        else if (delayHours > 24) warningCount++;
      });

      container.querySelector("#warning-count").textContent = warningCount;
      container.querySelector("#error-count").textContent = errorCount;
    }
  };

  // 初期ダッシュボード更新
  updateDashboard();
}

function(container, apiUrl, tables) {
  let currentTab = 'approval';
  let approvalHistoryData = [];
  let notificationHistoryData = [];

  // 承認履歴テーブル再描画関数
  function renderApprovalHistory(rows) {
    const tbody = container.querySelector('#approval-history-tbody');
    tbody.innerHTML = rows.map(r => {
      const statusBadge = getStatusBadge(r.承認結果 || '');
      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 10px; color: var(--text);">${r.申請書類番号 || ''}</td>
          <td style="padding: 6px 10px; color: var(--text);">${r.申請者名 || ''}</td>
          <td style="padding: 6px 10px; color: var(--text);">${r.承認者名 || ''}</td>
          <td style="padding: 6px 10px;">${statusBadge}</td>
          <td style="padding: 6px 10px; color: var(--text);">${formatDateTime(r.承認日時)}</td>
          <td style="padding: 6px 10px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.承認コメント || ''}">${r.承認コメント || ''}</td>
          <td style="padding: 6px 10px; color: var(--text);">${r.処理順序 || ''}</td>
        </tr>
      `;
    }).join('');
  }

  // 通知履歴テーブル再描画関数
  function renderNotificationHistory(rows) {
    const tbody = container.querySelector('#notification-history-tbody');
    tbody.innerHTML = rows.map(r => {
      const statusBadge = getNotificationStatusBadge(r.送信状態 || '');
      const readStatus = r.既読フラグ ? '既読' : '未読';
      const readBadge = r.既読フラグ ? 
        '<span style="background: rgba(34, 197, 94, 0.2); color: #22c55e; padding: 2px 6px; border-radius: 4px; font-size: 11px;">既読</span>' :
        '<span style="background: rgba(239, 68, 68, 0.2); color: #ef4444; padding: 2px 6px; border-radius: 4px; font-size: 11px;">未読</span>';

      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 10px; color: var(--text);">${r.通知種別 || ''}</td>
          <td style="padding: 6px 10px; color: var(--text);">${r.通知先ユーザー名 || ''}</td>
          <td style="padding: 6px 10px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${r.通知タイトル || ''}">${r.通知タイトル || ''}</td>
          <td style="padding: 6px 10px; color: var(--text);">${r.送信方法 || ''}</td>
          <td style="padding: 6px 10px;">${statusBadge}</td>
          <td style="padding: 6px 10px; color: var(--text);">${formatDateTime(r.送信日時)}</td>
          <td style="padding: 6px 10px;">${readBadge}</td>
        </tr>
      `;
    }).join('');
  }

  // ステータスバッジ生成
  function getStatusBadge(status) {
    const statusMap = {
      '承認': { bg: 'rgba(34, 197, 94, 0.2)', color: '#22c55e' },
      '否認': { bg: 'rgba(239, 68, 68, 0.2)', color: '#ef4444' },
      '保留': { bg: 'rgba(245, 158, 11, 0.2)', color: '#f59e0b' },
      '差戻し': { bg: 'rgba(168, 85, 247, 0.2)', color: '#a855f7' }
    };
    const style = statusMap[status] || { bg: 'rgba(156, 163, 175, 0.2)', color: '#9ca3af' };
    return `<span style="background: ${style.bg}; color: ${style.color}; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${status}</span>`;
  }

  // 通知ステータスバッジ生成
  function getNotificationStatusBadge(status) {
    const statusMap = {
      '送信完了': { bg: 'rgba(34, 197, 94, 0.2)', color: '#22c55e' },
      '送信失敗': { bg: 'rgba(239, 68, 68, 0.2)', color: '#ef4444' },
      '送信中': { bg: 'rgba(59, 130, 246, 0.2)', color: '#3b82f6' },
      '送信待ち': { bg: 'rgba(245, 158, 11, 0.2)', color: '#f59e0b' }
    };
    const style = statusMap[status] || { bg: 'rgba(156, 163, 175, 0.2)', color: '#9ca3af' };
    return `<span style="background: ${style.bg}; color: ${style.color}; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${status}</span>`;
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      // 承認履歴データ取得（承認履歴テーブル）
      const approvalRows = await window.aivicApi.list(6); // 承認履歴テーブル
      if (approvalRows) {
        approvalHistoryData = approvalRows;
        if (currentTab === 'approval') {
          renderApprovalHistory(approvalHistoryData);
        }
      }

      // 通知履歴データ取得（通知履歴テーブル）
      const notificationRows = await window.aivicApi.list(7); // 通知履歴テーブル
      if (notificationRows) {
        notificationHistoryData = notificationRows;
        if (currentTab === 'notification') {
          renderNotificationHistory(notificationHistoryData);
        }
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 検索フィルタ実行
  function performSearch() {
    const documentNumber = container.querySelector('#search-document-number').value.trim();
    const applicant = container.querySelector('#search-applicant').value;
    const documentType = container.querySelector('#search-document-type').value;
    const approvalStatus = container.querySelector('#search-approval-status').value;
    const startDate = container.querySelector('#search-start-date').value;
    const endDate = container.querySelector('#search-end-date').value;

    if (currentTab === 'approval') {
      let filtered = approvalHistoryData.filter(row => {
        if (documentNumber && !row.申請書類番号?.includes(documentNumber)) return false;
        if (applicant && row.申請者名 !== applicant) return false;
        if (documentType && row.文書種別 !== documentType) return false;
        if (approvalStatus && row.承認結果 !== approvalStatus) return false;
        if (startDate && row.承認日時 && new Date(row.承認日時) < new Date(startDate)) return false;
        if (endDate && row.承認日時 && new Date(row.承認日時) > new Date(endDate + 'T23:59:59')) return false;
        return true;
      });
      renderApprovalHistory(filtered);
    } else {
      let filtered = notificationHistoryData.filter(row => {
        if (documentNumber && !row.申請書類番号?.includes(documentNumber)) return false;
        if (applicant && row.通知先ユーザー名 !== applicant) return false;
        if (startDate && row.送信日時 && new Date(row.送信日時) < new Date(startDate)) return false;
        if (endDate && row.送信日時 && new Date(row.送信日時) > new Date(endDate + 'T23:59:59')) return false;
        return true;
      });
      renderNotificationHistory(filtered);
    }
  }

  // CSVエクスポート
  function exportToCSV(data, filename, headers) {
    if (!data || data.length === 0) {
      alert('エクスポートするデータがありません。');
      return;
    }

    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...data.map(row => headers.map(header => {
        const value = row[header] || '';
        return `"${String(value).replace(/"/g, '""')}"`;
      }).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    link.click();
  }

  // タブ切り替え
  function switchTab(tab) {
    currentTab = tab;

    // タブボタンのスタイル更新
    const approvalTab = container.querySelector('#tab-approval');
    const notificationTab = container.querySelector('#tab-notification');

    if (tab === 'approval') {
      approvalTab.style.color = 'var(--text)';
      approvalTab.style.borderBottomColor = 'var(--primary)';
      notificationTab.style.color = 'var(--text-muted)';
      notificationTab.style.borderBottomColor = 'transparent';

      container.querySelector('#approval-history-section').style.display = 'block';
      container.querySelector('#notification-history-section').style.display = 'none';

      renderApprovalHistory(approvalHistoryData);
    } else {
      notificationTab.style.color = 'var(--text)';
      notificationTab.style.borderBottomColor = 'var(--primary)';
      approvalTab.style.color = 'var(--text-muted)';
      approvalTab.style.borderBottomColor = 'transparent';

      container.querySelector('#approval-history-section').style.display = 'none';
      container.querySelector('#notification-history-section').style.display = 'block';

      renderNotificationHistory(notificationHistoryData);
    }
  }

  // イベントリスナー登録

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', performSearch);

  // クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', () => {
    container.querySelector('#search-document-number').value = '';
    container.querySelector('#search-applicant').value = '';
    container.querySelector('#search-document-type').value = '';
    container.querySelector('#search-approval-status').value = '';
    container.querySelector('#search-start-date').value = '';
    container.querySelector('#search-end-date').value = '';

    if (currentTab === 'approval') {
      renderApprovalHistory(approvalHistoryData);
    } else {
      renderNotificationHistory(notificationHistoryData);
    }
  });

  // タブ切り替え
  container.querySelector('#tab-approval').addEventListener('click', () => switchTab('approval'));
  container.querySelector('#tab-notification').addEventListener('click', () => switchTab('notification'));

  // CSVエクスポート - 承認履歴
  container.querySelector('#btn-export-approval').addEventListener('click', () => {
    const headers = ['申請書類番号', '申請者名', '承認者名', '承認結果', '承認日時', '承認コメント', '処理順序'];
    exportToCSV(approvalHistoryData, '承認履歴.csv', headers);
  });

  // CSVエクスポート - 通知履歴
  container.querySelector('#btn-export-notification').addEventListener('click', () => {
    const headers = ['通知種別', '通知先ユーザー名', '通知タイトル', '送信方法', '送信状態', '送信日時', '既読フラグ'];
    exportToCSV(notificationHistoryData, '通知履歴.csv', headers);
  });

  // 初期データ読み込み実行
  loadData();
}

function(container, apiUrl, tables) {
  // ファイルアップロード機能の初期化
  const fileUploadArea = container.querySelector('#file-upload-area');
  const fileInput = container.querySelector('#file-input');
  const fileList = container.querySelector('#file-list');
  let selectedFiles = [];

  // ファイルアップロードエリアのクリックイベント
  fileUploadArea.addEventListener('click', () => {
    fileInput.click();
  });

  // ドラッグ＆ドロップ機能
  fileUploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    fileUploadArea.style.borderColor = 'var(--primary)';
    fileUploadArea.style.background = 'rgba(255,255,255,0.05)';
  });

  fileUploadArea.addEventListener('dragleave', (e) => {
    e.preventDefault();
    fileUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    fileUploadArea.style.background = 'rgba(0,0,0,0.15)';
  });

  fileUploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    fileUploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    fileUploadArea.style.background = 'rgba(0,0,0,0.15)';

    const files = Array.from(e.dataTransfer.files);
    handleFileSelection(files);
  });

  // ファイル選択イベント
  fileInput.addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    handleFileSelection(files);
  });

  // ファイル選択処理
  function handleFileSelection(files) {
    selectedFiles = [...selectedFiles, ...files];
    renderFileList();
  }

  // ファイル一覧の描画
  function renderFileList() {
    if (selectedFiles.length === 0) {
      fileList.innerHTML = '';
      return;
    }

    fileList.innerHTML = selectedFiles.map((file, index) => `
      <div style="display: flex; justify-content: space-between; align-items: center; padding: 6px 10px; background: rgba(0,0,0,0.15); border-radius: 4px; margin-bottom: 4px;">
        <span style="font-size: 13px; color: var(--text);">${file.name} (${(file.size / 1024).toFixed(1)} KB)</span>
        <button type="button" class="file-remove-btn" data-index="${index}" style="background: transparent; border: none; color: var(--text-muted); cursor: pointer; font-size: 12px;">削除</button>
      </div>
    `).join('');
  }

  // ファイル削除機能
  container.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('.file-remove-btn');
    if (removeBtn) {
      const index = parseInt(removeBtn.dataset.index);
      selectedFiles.splice(index, 1);
      renderFileList();
    }
  });

  // 下書き保存ボタン
  container.querySelector('#btn-draft').addEventListener('click', async () => {
    const formData = collectFormData();
    formData.status = 'draft';

    try {
      const saved = await window.aivicApi.save(1, formData); // 申請書類テーブル
      if (saved) {
        alert('下書きを保存しました');
      } else {
        alert('保存に失敗しました');
      }
    } catch (error) {
      console.error('Draft save error:', error);
      alert('保存中にエラーが発生しました');
    }
  });

  // 文書種別判定ボタン（申請書類送信）
  container.querySelector('#btn-submit').addEventListener('click', async () => {
    const form = container.querySelector('#application-form');
    if (!form.checkValidity()) {
      form.reportValidity();
      return;
    }

    const formData = collectFormData();
    formData.status = 'submitted';

    try {
      const saved = await window.aivicApi.save(1, formData); // 申請書類テーブル
      if (saved) {
        alert('申請書類を送信しました');
        window.showScreen("scr-1779350024410"); // 文書種別判定画面
      } else {
        alert('送信に失敗しました');
      }
    } catch (error) {
      console.error('Submit error:', error);
      alert('送信中にエラーが発生しました');
    }
  });

  // フォームデータ収集
  function collectFormData() {
    const form = container.querySelector('#application-form');
    const formData = new FormData(form);

    // 基本データ
    const data = {
      申請タイトル: formData.get('title') || '',
      申請種別: formData.get('document_type') || '',
      申請内容: formData.get('content') || '',
      申請金額: formData.get('budget') ? parseInt(formData.get('budget')) : null,
      申請開始日: new Date().toISOString(),
      申請終了日: formData.get('desired_date') ? new Date(formData.get('desired_date')).toISOString() : null,
      承認状態: 'draft',
      承認段階: 1,
      緊急フラグ: formData.get('urgency') === 'high' || formData.get('urgency') === 'critical',
      添付ファイル有無: selectedFiles.length > 0,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      申請者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを取得
      作成者ID: 'current-user-id',
      更新者ID: 'current-user-id'
    };

    // 関連部署の収集
    const departments = [];
    container.querySelectorAll('input[name="departments"]:checked').forEach(cb => {
      departments.push(cb.value);
    });
    data.関連部署 = departments.join(',');

    // 申請理由
    data.申請理由 = formData.get('reason') || '';

    // 承認フロー
    data.承認フロー = formData.get('approval_flow') || '';

    // 承認者指定
    data.指定承認者 = formData.get('approver') || '';

    return data;
  }

  // 初期設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  container.querySelector('#desired-date').value = nextWeek.toISOString().split('T')[0];

  // 通常緊急度をデフォルト選択
  container.querySelector('input[name="urgency"][value="low"]').checked = true;
}

function(container, apiUrl, tables) {
  let currentFile = null;
  let detectionResult = null;

  // DOM要素の取得
  const uploadArea = container.querySelector('#upload-area');
  const fileInput = container.querySelector('#file-input');
  const btnSelectFile = container.querySelector('#btn-select-file');
  const fileInfo = container.querySelector('#file-info');
  const fileName = container.querySelector('#file-name');
  const fileSize = container.querySelector('#file-size');
  const processingStatus = container.querySelector('#processing-status');
  const statusText = container.querySelector('#status-text');
  const detectionResultDiv = container.querySelector('#detection-result');
  const detectedType = container.querySelector('#detected-type');
  const accuracyFill = container.querySelector('#accuracy-fill');
  const accuracyText = container.querySelector('#accuracy-text');
  const appliedRule = container.querySelector('#applied-rule');
  const manualTypeSelect = container.querySelector('#manual-type-select');
  const btnReprocess = container.querySelector('#btn-reprocess');
  const btnConfirm = container.querySelector('#btn-confirm');
  const errorMessage = container.querySelector('#error-message');
  const errorText = container.querySelector('#error-text');
  const previewArea = container.querySelector('#preview-area');
  const approvalFlow = container.querySelector('#approval-flow');
  const btnViewApproval = container.querySelector('#btn-view-approval');
  const appliedRulesCount = container.querySelector('#applied-rules-count');
  const matchConditions = container.querySelector('#match-conditions');
  const confidenceLevel = container.querySelector('#confidence-level');
  const historyList = container.querySelector('#history-list');

  // 文書種別マスタの取得
  const documentTypes = tables[2]?.records || [];

  // 判別ルールの取得
  const detectionRules = tables[9]?.records || [];

  // 履歴の初期表示
  function renderHistory() {
    const history = JSON.parse(localStorage.getItem('detectionHistory') || '[]');
    if (history.length === 0) {
      historyList.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 16px;">履歴がありません</div>';
      return;
    }

    historyList.innerHTML = history.slice(-10).reverse().map(item => `
      <div style="padding: 8px; border-bottom: 1px solid rgba(255,255,255,0.1); margin-bottom: 8px;">
        <div style="font-weight: 500; color: var(--text); margin-bottom: 2px;">${item.fileName}</div>
        <div style="color: var(--text-muted); margin-bottom: 2px;">${item.detectedType}</div>
        <div style="color: var(--text-muted); font-size: 11px;">${item.timestamp}</div>
      </div>
    `).join('');
  }

  // ファイル選択処理
  function handleFileSelect(file) {
    if (!file) return;

    currentFile = file;
    fileName.textContent = file.name;
    fileSize.textContent = formatFileSize(file.size);
    fileInfo.style.display = 'block';

    // プレビュー表示
    if (file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (e) => {
        previewArea.innerHTML = `<img src="${e.target.result}" style="max-width: 100%; max-height: 100%; object-fit: contain;">`;
      };
      reader.readAsDataURL(file);
    } else {
      previewArea.innerHTML = `<div style="text-align: center;"><div style="font-size: 48px; margin-bottom: 8px;">📄</div><div>${file.name}</div></div>`;
    }

    // 自動判別開始
    startDetection();
  }

  // ファイルサイズフォーマット
  function formatFileSize(bytes) {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }

  // 判別処理開始
  function startDetection() {
    if (!currentFile) return;

    processingStatus.style.display = 'block';
    statusText.textContent = '文書を解析中...';
    detectionResultDiv.style.display = 'none';
    errorMessage.style.display = 'none';

    // 模擬的な判別処理（実際はOCR + AI判別）
    setTimeout(() => {
      performDetection();
    }, 2000);
  }

  // 判別実行
  function performDetection() {
    const fileName = currentFile.name.toLowerCase();
    let bestMatch = null;
    let bestScore = 0;

    // ファイル名ベースの簡易判別
    const patterns = [
      { type: 'vacation', keywords: ['休暇', '有給', 'vacation'], name: '休暇申請書' },
      { type: 'expense', keywords: ['経費', '出張', 'expense'], name: '経費申請書' },
      { type: 'proposal', keywords: ['稟議', '提案', 'proposal'], name: '稟議書' },
      { type: 'purchase', keywords: ['購入', '調達', 'purchase'], name: '購入申請書' },
      { type: 'overtime', keywords: ['残業', '時間外', 'overtime'], name: '残業申請書' }
    ];

    patterns.forEach(pattern => {
      const matches = pattern.keywords.filter(keyword => fileName.includes(keyword));
      if (matches.length > 0) {
        const score = (matches.length / pattern.keywords.length) * 100;
        if (score > bestScore) {
          bestScore = score;
          bestMatch = pattern;
        }
      }
    });

    // デフォルト判別
    if (!bestMatch) {
      bestMatch = patterns[0];
      bestScore = 65;
    }

    detectionResult = {
      type: bestMatch.type,
      typeName: bestMatch.name,
      accuracy: bestScore,
      rule: 'ファイル名パターンマッチング',
      appliedRules: 1,
      matchConditions: bestMatch.keywords.join(', '),
      confidence: bestScore > 80 ? '高' : bestScore > 60 ? '中' : '低'
    };

    showDetectionResult();
  }

  // 判別結果表示
  function showDetectionResult() {
    processingStatus.style.display = 'none';
    detectionResultDiv.style.display = 'block';

    detectedType.textContent = detectionResult.typeName;
    accuracyFill.style.width = detectionResult.accuracy + '%';
    accuracyText.textContent = Math.round(detectionResult.accuracy) + '%';
    appliedRule.textContent = detectionResult.rule;

    // ルール適用状況更新
    appliedRulesCount.textContent = detectionResult.appliedRules;
    matchConditions.textContent = detectionResult.matchConditions;
    confidenceLevel.textContent = detectionResult.confidence;

    // 承認フロー表示
    updateApprovalFlow();

    // 履歴に追加
    addToHistory();
  }

  // 承認フロー更新
  function updateApprovalFlow() {
    const flowSteps = [
      '1. 申請者による提出',
      '2. 直属上司による承認',
      '3. 部門長による承認',
      '4. 人事部による最終確認'
    ];

    approvalFlow.innerHTML = flowSteps.map((step, index) => 
      `<div style="margin-bottom: 4px; color: ${index === 0 ? 'var(--primary)' : 'var(--text-muted)'};">${step}</div>`
    ).join('');

    btnViewApproval.disabled = false;
    btnViewApproval.style.opacity = '1';
  }

  // 履歴追加
  function addToHistory() {
    const history = JSON.parse(localStorage.getItem('detectionHistory') || '[]');
    history.push({
      fileName: currentFile.name,
      detectedType: detectionResult.typeName,
      accuracy: detectionResult.accuracy,
      timestamp: new Date().toLocaleString('ja-JP')
    });
    localStorage.setItem('detectionHistory', JSON.stringify(history));
    renderHistory();
  }

  // エラー表示
  function showError(message) {
    processingStatus.style.display = 'none';
    errorMessage.style.display = 'block';
    errorText.textContent = message;
  }

  // イベントリスナー設定
  btnSelectFile.addEventListener('click', () => {
    fileInput.click();
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFileSelect(e.target.files[0]);
    }
  });

  // ドラッグ&ドロップ
  uploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'var(--primary)';
  });

  uploadArea.addEventListener('dragleave', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  uploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';

    if (e.dataTransfer.files.length > 0) {
      handleFileSelect(e.dataTransfer.files[0]);
    }
  });

  uploadArea.addEventListener('click', () => {
    fileInput.click();
  });

  // 再判別ボタン
  btnReprocess.addEventListener('click', () => {
    if (currentFile) {
      startDetection();
    }
  });

  // 判別確定ボタン
  btnConfirm.addEventListener('click', async () => {
    if (!detectionResult) return;

    const finalType = manualTypeSelect.value || detectionResult.type;
    const finalTypeName = manualTypeSelect.value ? 
      manualTypeSelect.options[manualTypeSelect.selectedIndex].text : 
      detectionResult.typeName;

    // 申請書類として保存
    const applicationData = {
      申請者ID: 'current-user-id', // 実際は現在のユーザーID
      申請種別: finalType,
      申請タイトル: currentFile.name,
      申請内容: `自動判別により${finalTypeName}として分類されました。`,
      承認状態: '申請中',
      承認段階: 1,
      緊急フラグ: false,
      添付ファイル有無: true,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user-id',
      更新者ID: 'current-user-id'
    };

    try {
      const saved = await window.aivicApi.save(1, applicationData);
      if (saved) {
        alert('文書種別の判別が完了し、申請書類として登録されました。');
        // リセット
        currentFile = null;
        detectionResult = null;
        fileInfo.style.display = 'none';
        detectionResultDiv.style.display = 'none';
        previewArea.innerHTML = '文書を選択してください';
        manualTypeSelect.value = '';
        btnViewApproval.disabled = true;
      }
    } catch (error) {
      showError('申請書類の登録に失敗しました。');
    }
  });

  // 申請書類確認画面への遷移
  btnViewApproval.addEventListener('click', () => {
    window.showScreen("scr-1779349647621");
  });

  // 初期表示
  renderHistory();
}

function(container, apiUrl, tables) {
  let currentFlowId = null;
  let selectedApprover = null;

  // 承認ステップ再描画関数
  function renderSteps(steps) {
    const tbody = container.querySelector("#steps-tbody");
    tbody.innerHTML = steps.map(step => `
      <tr data-id="${step.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 6px 10px; font-size: 12px;">${step.ステップ番号 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${step.承認者名 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${step.承認者役職 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${step.必須承認フラグ ? 'rgba(255,100,100,0.2)' : 'rgba(100,255,100,0.2)'}; color: var(--text);">
            ${step.必須承認フラグ ? '必須' : '任意'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 12px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; background: ${step.並列承認フラグ ? 'rgba(100,150,255,0.2)' : 'rgba(150,150,150,0.2)'}; color: var(--text);">
            ${step.並列承認フラグ ? '並列' : '順次'}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 12px;">${step.承認期限日数 || ""}日</td>
        <td style="padding: 6px 10px; font-size: 12px;">${step.代理承認者名 || "-"}</td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary edit-step-btn" data-id="${step.id}" style="font-size: 11px; padding: 4px 8px; margin-right: 4px;">編集</button>
          <button class="action-btn secondary delete-step-btn" data-id="${step.id}" style="font-size: 11px; padding: 4px 8px; margin-right: 4px;">削除</button>
          <button class="action-btn secondary condition-btn" data-id="${step.id}" style="font-size: 11px; padding: 4px 8px;">条件</button>
        </td>
      </tr>
    `).join("");
  }

  // 承認者一覧を描画
  function renderApprovers(approvers) {
    const tbody = container.querySelector("#approvers-tbody");
    tbody.innerHTML = approvers.map(user => `
      <tr data-id="${user.id}" style="cursor: pointer; border-bottom: 1px solid rgba(255,255,255,0.05);" class="approver-row">
        <td style="padding: 6px 10px;">
          <input type="radio" name="approver" value="${user.id}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 12px;">${user.氏名 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${user.部署名 || ""}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${user.役職 || ""}</td>
      </tr>
    `).join("");
  }

  // 初期データ読み込み
  window.aivicApi.list(4).then(steps => {
    if (steps) renderSteps(steps);
  });

  // 承認者データ読み込み
  window.aivicApi.list(0).then(users => {
    if (users) renderApprovers(users);
  });

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    window.aivicApi.list(4).then(steps => {
      if (steps) {
        const filtered = steps.filter(step => 
          JSON.stringify(step).toLowerCase().includes(keyword)
        );
        renderSteps(filtered);
      }
    });
  });

  // ステップ追加ボタン
  container.querySelector("#btn-add-step").addEventListener("click", () => {
    const modal = container.querySelector("#approver-modal");
    modal.style.display = "block";
  });

  // フロー保存ボタン
  container.querySelector("#btn-save-flow").addEventListener("click", async () => {
    const documentType = container.querySelector("#select-document-type").value;
    const flowName = container.querySelector("#input-flow-name").value;
    const deadline = container.querySelector("#input-deadline").value;

    if (!documentType || !flowName) {
      alert("文書種別と承認フロー名を入力してください");
      return;
    }

    const flowData = {
      文書種別ID: documentType,
      承認フロー名: flowName,
      承認期限日数: parseInt(deadline) || 3,
      有効開始日: new Date().toISOString(),
      作成者ID: "current-user-id",
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(4, flowData);
    if (saved) {
      currentFlowId = saved.id;
      alert("承認フローを保存しました");
      window.aivicApi.list(4).then(renderSteps);
    }
  });

  // クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#select-document-type").value = "";
    container.querySelector("#input-flow-name").value = "";
    container.querySelector("#input-deadline").value = "3";
    currentFlowId = null;
  });

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#approver-modal").style.display = "none";
  });

  container.querySelector("#btn-cancel-selection").addEventListener("click", () => {
    container.querySelector("#approver-modal").style.display = "none";
  });

  // 承認者選択確定
  container.querySelector("#btn-confirm-selection").addEventListener("click", async () => {
    const selectedRadio = container.querySelector('input[name="approver"]:checked');
    if (!selectedRadio) {
      alert("承認者を選択してください");
      return;
    }

    const userId = selectedRadio.value;
    const required = container.querySelector("#check-required").checked;
    const parallel = container.querySelector("#check-parallel").checked;

    // 承認者情報を取得
    const users = await window.aivicApi.list(0);
    const user = users?.find(u => u.id === userId);

    if (!user) return;

    // 現在のステップ数を取得
    const currentSteps = await window.aivicApi.list(4);
    const stepNumber = (currentSteps?.length || 0) + 1;

    const stepData = {
      承認フローID: currentFlowId || "temp-flow-id",
      ステップ番号: stepNumber,
      承認者ID: userId,
      承認者名: user.氏名,
      承認者役職: user.役職,
      必須承認フラグ: required,
      並列承認フラグ: parallel,
      承認期限日数: parseInt(container.querySelector("#input-deadline").value) || 3,
      作成者ID: "current-user-id",
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(4, stepData);
    if (saved) {
      container.querySelector("#approver-modal").style.display = "none";
      container.querySelector("#check-required").checked = false;
      container.querySelector("#check-parallel").checked = false;
      window.aivicApi.list(4).then(renderSteps);
    }
  });

  // 承認者検索
  container.querySelector("#input-approver-search").addEventListener("input", async (e) => {
    const keyword = e.target.value.toLowerCase();
    const users = await window.aivicApi.list(0);
    if (users) {
      const filtered = users.filter(user => 
        (user.氏名 || "").toLowerCase().includes(keyword) ||
        (user.部署名 || "").toLowerCase().includes(keyword) ||
        (user.役職 || "").toLowerCase().includes(keyword)
      );
      renderApprovers(filtered);
    }
  });

  // 条件分岐モーダル
  container.querySelector("#btn-close-condition").addEventListener("click", () => {
    container.querySelector("#condition-modal").style.display = "none";
  });

  container.querySelector("#btn-cancel-condition").addEventListener("click", () => {
    container.querySelector("#condition-modal").style.display = "none";
  });

  container.querySelector("#btn-save-condition").addEventListener("click", () => {
    const field = container.querySelector("#select-condition-field").value;
    const operator = container.querySelector("#select-condition-operator").value;
    const value = container.querySelector("#input-condition-value").value;

    if (!field || !operator || !value) {
      alert("すべての条件を入力してください");
      return;
    }

    alert("条件分岐を保存しました");
    container.querySelector("#condition-modal").style.display = "none";
  });

  // イベントデリゲーション（編集・削除・条件設定）
  container.addEventListener("click", async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest(".delete-step-btn");
    if (deleteBtn) {
      if (!confirm("このステップを削除しますか？")) return;
      await window.aivicApi.delete(4, deleteBtn.dataset.id);
      window.aivicApi.list(4).then(renderSteps);
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest(".edit-step-btn");
    if (editBtn) {
      container.querySelector("#approver-modal").style.display = "block";
      return;
    }

    // 条件設定ボタン
    const conditionBtn = e.target.closest(".condition-btn");
    if (conditionBtn) {
      container.querySelector("#condition-modal").style.display = "block";
      return;
    }

    // 承認者行クリック
    const approverRow = e.target.closest(".approver-row");
    if (approverRow) {
      const radio = approverRow.querySelector('input[type="radio"]');
      if (radio) radio.checked = true;
      return;
    }
  });

  // 画面遷移
  container.querySelector('[data-testid="classification-settings-btn"]').addEventListener("click", () => {
    window.showScreen("scr-1779349693145");
  });

  container.querySelector('[data-testid="process-route-settings-btn"]').addEventListener("click", () => {
    window.showScreen("scr-1779350057855");
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#progress-tbody");
  const totalCountEl = container.querySelector("#total-count");
  const modal = container.querySelector("#progress-modal");

  // ユーザーデータの取得（申請者名表示用）
  let users = [];
  let documentTypes = [];

  async function loadReferenceData() {
    try {
      users = await window.aivicApi.list(0) || []; // ユーザーテーブル
      documentTypes = await window.aivicApi.list(2) || []; // 文書種別マスタ
    } catch (error) {
      console.error("参照データの読み込みに失敗:", error);
    }
  }

  function getUserName(userId) {
    const user = users.find(u => u.ユーザーID === userId);
    return user ? user.氏名 : "不明";
  }

  function getDocumentTypeName(typeId) {
    const docType = documentTypes.find(dt => dt.文書種別ID === typeId);
    return docType ? docType.文書種別名 : "不明";
  }

  function getStatusBadge(status) {
    const statusColors = {
      "申請中": "background: #1e40af; color: #dbeafe;",
      "承認済": "background: #16a34a; color: #dcfce7;",
      "却下": "background: #dc2626; color: #fecaca;",
      "取下げ": "background: #6b7280; color: #f3f4f6;",
      "保留": "background: #d97706; color: #fed7aa;"
    };
    const style = statusColors[status] || "background: #6b7280; color: #f3f4f6;";
    return `<span style="padding: 2px 8px; border-radius: 12px; font-size: 11px; font-weight: 500; ${style}">${status}</span>`;
  }

  function getProgressBar(currentStep, totalSteps) {
    const progress = Math.round((currentStep / totalSteps) * 100);
    return `
      <div style="width: 80px; background: rgba(255,255,255,0.1); border-radius: 10px; height: 6px; position: relative;">
        <div style="width: ${progress}%; background: var(--primary); border-radius: 10px; height: 100%;"></div>
      </div>
      <span style="font-size: 11px; color: var(--text-muted); margin-left: 4px;">${currentStep}/${totalSteps}</span>
    `;
  }

  function isDelayed(createdDate, currentStep) {
    const created = new Date(createdDate);
    const now = new Date();
    const daysDiff = Math.floor((now - created) / (1000 * 60 * 60 * 24));
    // 簡易的な遅延判定（3日以上経過している場合）
    return daysDiff > 3 && currentStep > 0;
  }

  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; padding: 20px; color: var(--text-muted);">データがありません</td></tr>';
      totalCountEl.textContent = "0";
      return;
    }

    tbody.innerHTML = rows.map(row => {
      const applicantName = getUserName(row.申請者ID);
      const docTypeName = getDocumentTypeName(row.申請種別);
      const currentApproverName = row.現在承認者ID ? getUserName(row.現在承認者ID) : "-";
      const statusBadge = getStatusBadge(row.承認状態);
      const progressBar = getProgressBar(row.承認段階 || 1, 3); // 仮に3段階とする
      const delayed = isDelayed(row.作成日時, row.承認段階);
      const delayedBadge = delayed ? '<span style="color: #dc2626; font-size: 11px;">⚠ 遅延</span>' : "-";
      const createdDate = new Date(row.作成日時).toLocaleDateString('ja-JP');

      return `
        <tr data-id="${row.申請書類ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請書類ID?.slice(-8) || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${applicantName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${docTypeName}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${row.申請タイトル || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${createdDate}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${statusBadge}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${currentApproverName}</td>
          <td style="padding: 6px 10px; font-size: 13px; display: flex; align-items: center;">${progressBar}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${delayedBadge}</td>
          <td style="padding: 6px 10px; font-size: 13px;">
            <button class="action-btn secondary detail-btn" data-id="${row.申請書類ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer; margin-right: 4px;">詳細</button>
            <button class="action-btn secondary progress-btn" data-id="${row.申請書類ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">進捗</button>
          </td>
        </tr>
      `;
    }).join("");

    totalCountEl.textContent = rows.length.toString();
  }

  async function loadAndRenderData() {
    try {
      const applications = await window.aivicApi.list(1) || []; // 申請書類テーブル
      renderRows(applications);
    } catch (error) {
      console.error("データの読み込みに失敗:", error);
      renderRows([]);
    }
  }

  function filterData() {
    const applicationId = container.querySelector("#search-application-id").value.trim();
    const applicantName = container.querySelector("#search-applicant-name").value.trim();
    const documentType = container.querySelector("#filter-document-type").value;
    const approvalStatus = container.querySelector("#filter-approval-status").value;
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const delayedOnly = container.querySelector("#filter-delayed").checked;

    window.aivicApi.list(1).then(applications => {
      let filtered = applications.filter(app => {
        // 申請番号フィルター
        if (applicationId && !app.申請書類ID?.includes(applicationId)) return false;

        // 申請者名フィルター
        if (applicantName) {
          const userName = getUserName(app.申請者ID);
          if (!userName.includes(applicantName)) return false;
        }

        // 文書種別フィルター
        if (documentType) {
          const docTypeName = getDocumentTypeName(app.申請種別);
          if (docTypeName !== documentType) return false;
        }

        // 承認状況フィルター
        if (approvalStatus && app.承認状態 !== approvalStatus) return false;

        // 申請日フィルター
        if (dateFrom || dateTo) {
          const appDate = new Date(app.作成日時);
          if (dateFrom && appDate < new Date(dateFrom)) return false;
          if (dateTo && appDate > new Date(dateTo + "T23:59:59")) return false;
        }

        // 遅延案件フィルター
        if (delayedOnly && !isDelayed(app.作成日時, app.承認段階)) return false;

        return true;
      });

      renderRows(filtered);
    });
  }

  function exportCSV() {
    window.aivicApi.list(1).then(applications => {
      const headers = ["申請番号", "申請者", "文書種別", "申請タイトル", "申請日", "承認状況", "現在承認者", "承認段階"];
      const csvContent = [
        headers.join(","),
        ...applications.map(app => [
          app.申請書類ID?.slice(-8) || "",
          getUserName(app.申請者ID),
          getDocumentTypeName(app.申請種別),
          app.申請タイトル || "",
          new Date(app.作成日時).toLocaleDateString('ja-JP'),
          app.承認状態 || "",
          app.現在承認者ID ? getUserName(app.現在承認者ID) : "",
          app.承認段階 || ""
        ].map(field => `"${field}"`).join(","))
      ].join("\n");

      const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "progress_report.csv";
      link.click();
    });
  }

  async function showProgressModal(applicationId) {
    try {
      // 申請書類の詳細を取得
      const applications = await window.aivicApi.list(1);
      const application = applications.find(app => app.申請書類ID === applicationId);
      if (!application) return;

      // 承認履歴を取得
      const approvalHistory = await window.aivicApi.list(5) || []; // 承認履歴テーブル
      const appHistory = approvalHistory.filter(h => h.申請書類ID === applicationId);

      // モーダル内容を更新
      container.querySelector("#modal-application-id").textContent = applicationId.slice(-8);

      // 進捗フローの表示
      const progressFlow = container.querySelector("#progress-flow");
      const steps = ["申請", "1次承認", "2次承認", "完了"];
      const currentStep = application.承認段階 || 1;

      progressFlow.innerHTML = steps.map((step, index) => {
        const isActive = index < currentStep;
        const isCurrent = index === currentStep - 1;
        const style = isActive 
          ? "background: var(--primary); color: #fff;" 
          : isCurrent 
            ? "background: #d97706; color: #fff;"
            : "background: rgba(255,255,255,0.1); color: var(--text-muted);";

        return `
          <div style="padding: 6px 12px; border-radius: 16px; font-size: 11px; font-weight: 500; ${style}">
            ${step}
          </div>
          ${index < steps.length - 1 ? '<div style="width: 20px; height: 2px; background: rgba(255,255,255,0.2);"></div>' : ''}
        `;
      }).join("");

      // 承認履歴の表示
      const historyContainer = container.querySelector("#approval-history");
      if (appHistory.length > 0) {
        historyContainer.innerHTML = appHistory.map(h => {
          const approverName = getUserName(h.承認者ID);
          const date = new Date(h.承認日時).toLocaleString('ja-JP');
          const resultColor = h.承認結果 === "承認" ? "#16a34a" : h.承認結果 === "却下" ? "#dc2626" : "#d97706";

          return `
            <div style="padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,0.1);">
              <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
                <span style="font-size: 13px; font-weight: 500; color: var(--text);">${approverName}</span>
                <span style="font-size: 11px; color: var(--text-muted);">${date}</span>
              </div>
              <div style="display: flex; align-items: center; gap: 8px;">
                <span style="padding: 2px 6px; border-radius: 8px; font-size: 10px; font-weight: 500; background: ${resultColor}; color: #fff;">${h.承認結果}</span>
                ${h.承認コメント ? `<span style="font-size: 12px; color: var(--text-muted);">${h.承認コメント}</span>` : ''}
              </div>
            </div>
          `;
        }).join("");
      } else {
        historyContainer.innerHTML = '<div style="text-align: center; color: var(--text-muted); font-size: 12px;">承認履歴がありません</div>';
      }

      modal.style.display = "block";
    } catch (error) {
      console.error("進捗詳細の取得に失敗:", error);
    }
  }

  // イベントリスナーの設定
  container.querySelector("#btn-search").addEventListener("click", filterData);
  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  container.querySelector("#close-modal").addEventListener("click", () => {
    modal.style.display = "none";
  });

  modal.addEventListener("click", (e) => {
    if (e.target === modal) {
      modal.style.display = "none";
    }
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const progressBtn = e.target.closest(".progress-btn");

    if (detailBtn) {
      const applicationId = detailBtn.dataset.id;
      window.showScreen("scr-1779349647621"); // 申請書類確認画面
    }

    if (progressBtn) {
      const applicationId = progressBtn.dataset.id;
      showProgressModal(applicationId);
    }
  });

  // 初期化
  loadReferenceData().then(() => {
    loadAndRenderData();
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#cases-tbody");

  // 滞留日数を計算する関数
  function calculateStagnantDays(createdAt) {
    const created = new Date(createdAt);
    const now = new Date();
    const diffTime = Math.abs(now - created);
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays;
  }

  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="padding: 20px; text-align: center; color: var(--text-muted);">該当する滞留案件がありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const stagnantDays = calculateStagnantDays(r.作成日時 || r.createdAt || new Date());
      const urgencyBadge = r.緊急フラグ || r.emergencyFlag ? 
        '<span style="background: #ff4444; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">緊急</span>' : 
        '<span style="background: rgba(255,255,255,0.1); color: var(--text-muted); padding: 2px 6px; border-radius: 4px; font-size: 11px;">通常</span>';

      return `
        <tr data-id="${r.id || r.申請書類ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px;">
            <input type="checkbox" class="case-checkbox" data-id="${r.id || r.申請書類ID}" style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請書類ID || r.id || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請種別 || r.documentType || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.申請者名 || r.applicantName || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.現在承認者名 || r.currentApproverName || ""}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.承認段階 || r.approvalStage || ""}次承認</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">
            <span style="color: ${stagnantDays > 7 ? '#ff6a00' : stagnantDays > 3 ? '#ffa500' : 'var(--text)'};">${stagnantDays}日</span>
          </td>
          <td style="padding: 6px 10px; font-size: 13px;">${urgencyBadge}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${new Date(r.作成日時 || r.createdAt || new Date()).toLocaleDateString()}</td>
          <td style="padding: 6px 10px;">
            <button class="action-btn secondary detail-btn" data-id="${r.id || r.申請書類ID}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データを即座に描画
  let allCases = tables[0]?.records || [];
  renderRows(allCases);

  // 最新データを取得
  window.aivicApi.list(0).then(rows => {
    if (rows) {
      allCases = rows;
      renderRows(rows);
    }
  });

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const documentType = container.querySelector("#document-type").value;
    const approvalStep = container.querySelector("#approval-step").value;
    const applicantName = container.querySelector("#applicant-name").value;
    const approverName = container.querySelector("#approver-name").value;
    const documentNumber = container.querySelector("#document-number").value;
    const daysMin = container.querySelector("#days-min").value;
    const daysMax = container.querySelector("#days-max").value;
    const urgency = container.querySelector('input[name="urgency"]:checked')?.value;

    // 最新データを取得してフィルタリング
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const filtered = rows.filter(r => {
      // 滞留期間フィルタ
      if (startDate) {
        const createdDate = new Date(r.作成日時 || r.createdAt);
        if (createdDate < new Date(startDate)) return false;
      }
      if (endDate) {
        const createdDate = new Date(r.作成日時 || r.createdAt);
        if (createdDate > new Date(endDate)) return false;
      }

      // 文書種別フィルタ
      if (documentType && (r.申請種別 || r.documentType) !== documentType) return false;

      // 承認ステップフィルタ
      if (approvalStep && (r.承認段階 || r.approvalStage) != approvalStep) return false;

      // 申請者名フィルタ
      if (applicantName && !(r.申請者名 || r.applicantName || "").includes(applicantName)) return false;

      // 承認者名フィルタ
      if (approverName && !(r.現在承認者名 || r.currentApproverName || "").includes(approverName)) return false;

      // 申請書類番号フィルタ
      if (documentNumber && !(r.申請書類ID || r.id || "").includes(documentNumber)) return false;

      // 滞留日数フィルタ
      const stagnantDays = calculateStagnantDays(r.作成日時 || r.createdAt);
      if (daysMin && stagnantDays < parseInt(daysMin)) return false;
      if (daysMax && stagnantDays > parseInt(daysMax)) return false;

      // 緊急度フィルタ
      if (urgency !== undefined && urgency !== "") {
        const isUrgent = r.緊急フラグ || r.emergencyFlag;
        if (urgency === "true" && !isUrgent) return false;
        if (urgency === "false" && isUrgent) return false;
      }

      return true;
    });

    renderRows(filtered);
  });

  // 4. クリアボタンのイベントリスナー
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#start-date").value = "";
    container.querySelector("#end-date").value = "";
    container.querySelector("#document-type").value = "";
    container.querySelector("#approval-step").value = "";
    container.querySelector("#applicant-name").value = "";
    container.querySelector("#approver-name").value = "";
    container.querySelector("#document-number").value = "";
    container.querySelector("#days-min").value = "";
    container.querySelector("#days-max").value = "";
    container.querySelectorAll('input[name="urgency"]').forEach(radio => radio.checked = false);

    renderRows(allCases);
  });

  // 5. CSVエクスポートボタンのイベントリスナー
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows || rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["申請書類番号", "申請種別", "申請者", "現在承認者", "承認段階", "滞留日数", "緊急度", "申請日時"];
    const csvData = [headers.join(",")];

    rows.forEach(r => {
      const stagnantDays = calculateStagnantDays(r.作成日時 || r.createdAt);
      const urgency = (r.緊急フラグ || r.emergencyFlag) ? "緊急" : "通常";
      const row = [
        r.申請書類ID || r.id || "",
        r.申請種別 || r.documentType || "",
        r.申請者名 || r.applicantName || "",
        r.現在承認者名 || r.currentApproverName || "",
        (r.承認段階 || r.approvalStage || "") + "次承認",
        stagnantDays + "日",
        urgency,
        new Date(r.作成日時 || r.createdAt || new Date()).toLocaleDateString()
      ];
      csvData.push(row.map(field => `"${field}"`).join(","));
    });

    const csvContent = "\uFEFF" + csvData.join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "stagnant_cases_" + new Date().toISOString().split('T')[0] + ".csv";
    link.click();
  });

  // 6. 催促通知送信ボタンのイベントリスナー
  container.querySelector("#btn-notify").addEventListener("click", () => {
    const selectedCheckboxes = container.querySelectorAll(".case-checkbox:checked");
    if (selectedCheckboxes.length === 0) {
      alert("催促通知を送信する案件を選択してください");
      return;
    }
    window.showScreen("scr-1779349608362");
  });

  // 7. 全選択チェックボックスのイベントリスナー
  container.querySelector("#select-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".case-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 8. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細画面への遷移（実装は要件に応じて）
      alert(`申請書類ID: ${id} の詳細表示機能は別画面で実装予定です`);
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector('#delayed-applications-tbody');
  const selectedCountEl = container.querySelector('#selected-count');
  const sendReminderBtn = container.querySelector('#btn-send-reminder');
  const historyModal = container.querySelector('#reminder-history-modal');
  const historyTbody = container.querySelector('#reminder-history-tbody');

  let allRows = [];
  let selectedIds = new Set();

  // 遅延日数を計算する関数
  function calculateDelayDays(createdAt, approvalDeadline) {
    const now = new Date();
    const deadline = new Date(approvalDeadline || createdAt);
    const diffTime = now - deadline;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return Math.max(0, diffDays);
  }

  // 催促履歴の件数を取得する関数
  function getReminderCount(applicationId) {
    const notifications = tables[6]?.records || [];
    return notifications.filter(n => 
      n.申請書類ID === applicationId && 
      n.通知種別 === '催促通知'
    ).length;
  }

  // テーブル再描画関数
  function renderRows(rows) {
    allRows = rows;
    tbody.innerHTML = rows.map(row => {
      const applicant = (tables[0]?.records || []).find(u => u.ユーザーID === row.申請者ID);
      const approver = (tables[0]?.records || []).find(u => u.ユーザーID === row.現在承認者ID);
      const docType = (tables[2]?.records || []).find(d => d.文書種別ID === row.申請種別);

      const delayDays = calculateDelayDays(row.作成日時, row.承認期限);
      const reminderCount = getReminderCount(row.申請書類ID);
      const isSelected = selectedIds.has(row.申請書類ID);

      // 遅延がない場合は表示しない
      if (delayDays === 0) return '';

      return `
        <tr data-id="${row.申請書類ID}" style="height: 36px;">
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02);">
            <input type="checkbox" class="row-checkbox" data-id="${row.申請書類ID}" ${isSelected ? 'checked' : ''} style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 13px; color: var(--text);">${row.申請書類ID?.substring(0, 8) || ''}</td>
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 13px; color: var(--text);">${applicant?.氏名 || ''}</td>
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 13px; color: var(--text);">${docType?.文書種別名 || row.申請種別 || ''}</td>
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 13px; color: var(--text);">${new Date(row.作成日時).toLocaleDateString('ja-JP')}</td>
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 13px; color: var(--text);">${approver?.氏名 || ''}</td>
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 13px;">
            <span style="background: ${delayDays >= 7 ? '#dc3545' : delayDays >= 3 ? '#fd7e14' : '#ffc107'}; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${delayDays}日</span>
          </td>
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 13px; color: var(--text);">${row.承認期限 ? new Date(row.承認期限).toLocaleDateString('ja-JP') : '-'}</td>
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 13px; color: var(--text);">
            ${reminderCount > 0 ? `<button class="view-history-btn" data-id="${row.申請書類ID}" style="background: none; border: none; color: var(--primary); cursor: pointer; text-decoration: underline; font-size: 12px;">${reminderCount}件</button>` : '0件'}
          </td>
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02);">
            <button class="individual-reminder-btn action-btn secondary" data-id="${row.申請書類ID}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">個別送信</button>
          </td>
        </tr>
      `;
    }).filter(html => html).join('');

    updateSelectedCount();
  }

  // 選択数更新
  function updateSelectedCount() {
    selectedCountEl.textContent = `選択: ${selectedIds.size}件`;
    sendReminderBtn.disabled = selectedIds.size === 0;
    if (selectedIds.size === 0) {
      sendReminderBtn.style.opacity = '0.5';
    } else {
      sendReminderBtn.style.opacity = '1';
    }
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(rows => {
    if (rows) {
      // 承認中の申請のみフィルタ
      const pendingApplications = rows.filter(r => r.承認状態 === '申請中' || r.承認状態 === '承認待ち');
      renderRows(pendingApplications);
    }
  });

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const documentId = container.querySelector('#search-document-id').value;
    const documentType = container.querySelector('#filter-document-type').value;
    const delayDays = container.querySelector('#filter-delay-days').value;

    const rows = await window.aivicApi.list(1);
    if (!rows) return;

    let filtered = rows.filter(r => r.承認状態 === '申請中' || r.承認状態 === '承認待ち');

    if (documentId) {
      filtered = filtered.filter(r => r.申請書類ID?.includes(documentId));
    }

    if (documentType) {
      filtered = filtered.filter(r => r.申請種別 === documentType);
    }

    if (delayDays) {
      const minDays = parseInt(delayDays);
      filtered = filtered.filter(r => {
        const delay = calculateDelayDays(r.作成日時, r.承認期限);
        return delay >= minDays;
      });
    }

    renderRows(filtered);
  });

  // 全選択・全解除
  container.querySelector('#btn-select-all').addEventListener('click', () => {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = true;
      selectedIds.add(cb.dataset.id);
    });
    updateSelectedCount();
  });

  container.querySelector('#btn-deselect-all').addEventListener('click', () => {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => {
      cb.checked = false;
    });
    selectedIds.clear();
    updateSelectedCount();
  });

  // 催促通知送信
  container.querySelector('#btn-send-reminder').addEventListener('click', async () => {
    if (selectedIds.size === 0) return;

    if (!confirm(`選択した${selectedIds.size}件の申請に催促通知を送信しますか？`)) return;

    let successCount = 0;
    let failCount = 0;

    for (const applicationId of selectedIds) {
      const application = allRows.find(r => r.申請書類ID === applicationId);
      if (!application) continue;

      const approver = (tables[0]?.records || []).find(u => u.ユーザーID === application.現在承認者ID);
      if (!approver) continue;

      // 通知履歴を作成
      const notification = {
        申請書類ID: applicationId,
        通知先ユーザーID: application.現在承認者ID,
        通知種別: '催促通知',
        通知タイトル: '承認催促のお知らせ',
        通知内容: `申請書類「${application.申請タイトル}」の承認が期限を過ぎています。速やかな承認をお願いいたします。`,
        送信方法: 'メール',
        送信状態: '送信完了',
        送信日時: new Date().toISOString(),
        既読フラグ: false,
        再送回数: 0,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者ID: 'system'
      };

      const saved = await window.aivicApi.save(6, notification);
      if (saved) {
        successCount++;
      } else {
        failCount++;
      }
    }

    alert(`催促通知送信完了\n成功: ${successCount}件\n失敗: ${failCount}件`);

    // 選択をクリア
    selectedIds.clear();
    renderRows(allRows);

    // 承認案件通知画面に遷移
    window.showScreen("scr-1779349619662");
  });

  // CSVエクスポート
  container.querySelector('#btn-csv-export').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(1);
    if (!rows) return;

    const delayedRows = rows.filter(r => {
      const delay = calculateDelayDays(r.作成日時, r.承認期限);
      return delay > 0 && (r.承認状態 === '申請中' || r.承認状態 === '承認待ち');
    });

    const headers = ['申請書類ID', '申請者名', '文書種別', '申請日時', '現在承認者', '遅延日数', '承認期限', '催促履歴件数'];
    const csvData = [headers.join(',')];

    delayedRows.forEach(row => {
      const applicant = (tables[0]?.records || []).find(u => u.ユーザーID === row.申請者ID);
      const approver = (tables[0]?.records || []).find(u => u.ユーザーID === row.現在承認者ID);
      const docType = (tables[2]?.records || []).find(d => d.文書種別ID === row.申請種別);
      const delayDays = calculateDelayDays(row.作成日時, row.承認期限);
      const reminderCount = getReminderCount(row.申請書類ID);

      const csvRow = [
        `"${row.申請書類ID || ''}"`,
        `"${applicant?.氏名 || ''}"`,
        `"${docType?.文書種別名 || row.申請種別 || ''}"`,
        `"${new Date(row.作成日時).toLocaleDateString('ja-JP')}"`,
        `"${approver?.氏名 || ''}"`,
        delayDays,
        `"${row.承認期限 ? new Date(row.承認期限).toLocaleDateString('ja-JP') : ''}"`,
        reminderCount
      ];
      csvData.push(csvRow.join(','));
    });

    const csv = '\uFEFF' + csvData.join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `遅延申請一覧_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  });

  // 更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(1);
    if (rows) {
      const pendingApplications = rows.filter(r => r.承認状態 === '申請中' || r.承認状態 === '承認待ち');
      renderRows(pendingApplications);
    }
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // チェックボックス
    const checkbox = e.target.closest('.row-checkbox');
    if (checkbox) {
      const id = checkbox.dataset.id;
      if (checkbox.checked) {
        selectedIds.add(id);
      } else {
        selectedIds.delete(id);
      }
      updateSelectedCount();
      return;
    }

    // 個別催促送信
    const individualBtn = e.target.closest('.individual-reminder-btn');
    if (individualBtn) {
      const applicationId = individualBtn.dataset.id;
      const application = allRows.find(r => r.申請書類ID === applicationId);
      if (!application) return;

      if (!confirm('この申請に催促通知を送信しますか？')) return;

      const approver = (tables[0]?.records || []).find(u => u.ユーザーID === application.現在承認者ID);
      if (!approver) {
        alert('承認者が見つかりません');
        return;
      }

      const notification = {
        申請書類ID: applicationId,
        通知先ユーザーID: application.現在承認者ID,
        通知種別: '催促通知',
        通知タイトル: '承認催促のお知らせ',
        通知内容: `申請書類「${application.申請タイトル}」の承認が期限を過ぎています。速やかな承認をお願いいたします。`,
        送信方法: 'メール',
        送信状態: '送信完了',
        送信日時: new Date().toISOString(),
        既読フラグ: false,
        再送回数: 0,
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者ID: 'system'
      };

      const saved = await window.aivicApi.save(6, notification);
      if (saved) {
        alert('催促通知を送信しました');
        renderRows(allRows);
      } else {
        alert('送信に失敗しました');
      }
      return;
    }

    // 履歴表示
    const historyBtn = e.target.closest('.view-history-btn');
    if (historyBtn) {
      const applicationId = historyBtn.dataset.id;
      const notifications = (tables[6]?.records || []).filter(n => 
        n.申請書類ID === applicationId && n.通知種別 === '催促通知'
      );

      historyTbody.innerHTML = notifications.map(n => {
        const recipient = (tables[0]?.records || []).find(u => u.ユーザーID === n.通知先ユーザーID);
        return `
          <tr>
            <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 12px;">${new Date(n.送信日時).toLocaleString('ja-JP')}</td>
            <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 12px;">${n.通知種別}</td>
            <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 12px;">${recipient?.氏名 || ''}</td>
            <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.02); font-size: 12px;">
              <span style="color: ${n.送信状態 === '送信完了' ? '#28a745' : '#dc3545'};">${n.送信状態}</span>
            </td>
          </tr>
        `;
      }).join('');

      historyModal.style.display = 'block';
      return;
    }

    // モーダル閉じる
    if (e.target.closest('#close-history-modal')) {
      historyModal.style.display = 'none';
      return;
    }
  });

  // モーダル背景クリックで閉じる
  historyModal.addEventListener('click', (e) => {
    if (e.target === historyModal) {
      historyModal.style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  let currentApplications = [];
  let selectedIds = new Set();

  // 再描画関数の定義
  function renderApprovals(applications) {
    const tbody = container.querySelector("#approval-tbody");
    if (!applications || applications.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; padding: 20px; color: var(--text-muted);">承認待ちの案件はありません</td></tr>';
      updateCounts([]);
      return;
    }

    tbody.innerHTML = applications.map(app => {
      const urgencyBadge = getUrgencyBadge(app);
      const delayIcon = getDelayIcon(app);
      const applicantName = getUserName(app.申請者ID);
      const documentTypeName = getDocumentTypeName(app.申請種別);

      return `
        <tr data-id="${app.申請書類ID}" style="height: 36px;">
          <td style="padding: 6px 10px;">
            <input type="checkbox" class="row-checkbox" data-id="${app.申請書類ID}" style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px;">${urgencyBadge}</td>
          <td style="padding: 6px 10px; color: var(--text);">${applicantName}</td>
          <td style="padding: 6px 10px; color: var(--text);">${documentTypeName}</td>
          <td style="padding: 6px 10px; color: var(--text);">${app.申請タイトル || ""}</td>
          <td style="padding: 6px 10px; color: var(--text-muted); font-size: 12px;">${formatDateTime(app.作成日時)}</td>
          <td style="padding: 6px 10px; color: var(--text-muted); font-size: 12px;">${getApprovalDeadline(app)}</td>
          <td style="padding: 6px 10px; text-align: center;">${delayIcon}</td>
          <td style="padding: 6px 10px;">
            <div style="display: flex; gap: 4px;">
              <button class="action-btn secondary detail-btn" data-id="${app.申請書類ID}" style="font-size: 11px; padding: 4px 8px;">詳細</button>
              <button class="action-btn approve-btn" data-id="${app.申請書類ID}" style="font-size: 11px; padding: 4px 8px;">承認</button>
            </div>
          </td>
        </tr>
      `;
    }).join("");

    updateCounts(applications);
  }

  function getUrgencyBadge(app) {
    if (app.緊急フラグ) {
      return '<span style="background: #ff6b00; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 500;">緊急</span>';
    }
    if (isOverdue(app)) {
      return '<span style="background: #ffc107; color: #000; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 500;">期限超過</span>';
    }
    return '<span style="background: #28a745; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 500;">通常</span>';
  }

  function getDelayIcon(app) {
    if (isOverdue(app)) {
      return '<span style="color: #ff6b00; font-size: 14px;" title="期限超過">⚠️</span>';
    }
    return '';
  }

  function isOverdue(app) {
    const deadline = getApprovalDeadlineDate(app);
    return deadline && new Date() > deadline;
  }

  function getApprovalDeadlineDate(app) {
    if (!app.作成日時) return null;
    const created = new Date(app.作成日時);
    created.setDate(created.getDate() + 3); // デフォルト3日
    return created;
  }

  function getApprovalDeadline(app) {
    const deadline = getApprovalDeadlineDate(app);
    return deadline ? formatDateTime(deadline.toISOString()) : '-';
  }

  function getUserName(userId) {
    const users = tables.find(t => t.tableName === 'ユーザー');
    if (!users || !users.records) return 'Unknown';
    const user = users.records.find(u => u.ユーザーID === userId);
    return user ? user.氏名 : 'Unknown';
  }

  function getDocumentTypeName(typeId) {
    const docTypes = tables.find(t => t.tableName === '文書種別マスタ');
    if (!docTypes || !docTypes.records) return typeId || 'Unknown';
    const docType = docTypes.records.find(dt => dt.文書種別ID === typeId);
    return docType ? docType.文書種別名 : typeId || 'Unknown';
  }

  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return `${date.getMonth() + 1}/${date.getDate()} ${date.getHours().toString().padStart(2, '0')}:${date.getMinutes().toString().padStart(2, '0')}`;
  }

  function updateCounts(applications) {
    const urgent = applications.filter(app => app.緊急フラグ).length;
    const overdue = applications.filter(app => isOverdue(app)).length;
    const normal = applications.filter(app => !app.緊急フラグ && !isOverdue(app)).length;
    const total = applications.length;

    container.querySelector("#urgent-count").textContent = urgent;
    container.querySelector("#overdue-count").textContent = overdue;
    container.querySelector("#normal-count").textContent = normal;
    container.querySelector("#total-count").textContent = total;
  }

  function filterApplications() {
    const urgencyFilter = container.querySelector("#filter-urgency").value;
    const documentTypeFilter = container.querySelector("#filter-document-type").value;
    const searchText = container.querySelector("#input-search").value.toLowerCase();

    let filtered = currentApplications.filter(app => {
      // 承認待ちのもののみ
      if (app.承認状態 !== '申請中') return false;

      // 緊急度フィルター
      if (urgencyFilter === 'urgent' && !app.緊急フラグ) return false;
      if (urgencyFilter === 'overdue' && !isOverdue(app)) return false;
      if (urgencyFilter === 'normal' && (app.緊急フラグ || isOverdue(app))) return false;

      // 文書種別フィルター
      if (documentTypeFilter && getDocumentTypeName(app.申請種別) !== documentTypeFilter) return false;

      // 申請者名検索
      if (searchText && !getUserName(app.申請者ID).toLowerCase().includes(searchText)) return false;

      return true;
    });

    renderApprovals(filtered);
  }

  function exportCSV() {
    const headers = ['緊急度', '申請者', '文書種別', '申請タイトル', '申請日時', '承認期限', '遅延状況'];
    const rows = currentApplications.map(app => [
      app.緊急フラグ ? '緊急' : (isOverdue(app) ? '期限超過' : '通常'),
      getUserName(app.申請者ID),
      getDocumentTypeName(app.申請種別),
      app.申請タイトル || '',
      formatDateTime(app.作成日時),
      getApprovalDeadline(app),
      isOverdue(app) ? '期限超過' : '正常'
    ]);

    const csvContent = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${(cell || '').toString().replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `承認案件一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  function showApprovalModal(applicationId) {
    const app = currentApplications.find(a => a.申請書類ID === applicationId);
    if (!app) return;

    const modal = container.querySelector("#approval-modal");
    container.querySelector("#modal-title").textContent = app.申請タイトル || '';
    container.querySelector("#modal-applicant").textContent = getUserName(app.申請者ID);
    container.querySelector("#modal-document-type").textContent = getDocumentTypeName(app.申請種別);
    container.querySelector("#approval-comment").value = '';

    modal.style.display = 'block';
    modal.dataset.applicationId = applicationId;
  }

  async function processApproval(applicationId, result, comment) {
    try {
      // 承認履歴に記録
      const historyData = {
        申請書類ID: applicationId,
        承認者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを使用
        承認結果: result,
        承認コメント: comment,
        承認日時: new Date().toISOString(),
        処理順序: 1
      };

      const saved = await window.aivicApi.save(4, historyData); // 承認履歴テーブル
      if (saved) {
        // 申請書類の状態を更新
        const updateData = {
          承認状態: result === '承認' ? '承認済' : (result === '差戻し' ? '差戻し' : '保留'),
          最終承認者ID: 'current-user-id',
          最終承認日時: result === '承認' ? new Date().toISOString() : null
        };

        await window.aivicApi.update(1, applicationId, updateData); // 申請書類テーブル

        // 一覧を再読み込み
        loadApplications();

        // モーダルを閉じる
        container.querySelector("#approval-modal").style.display = 'none';

        alert(`${result}処理が完了しました。`);
      }
    } catch (error) {
      console.error('承認処理エラー:', error);
      alert('処理中にエラーが発生しました。');
    }
  }

  async function loadApplications() {
    try {
      const applications = await window.aivicApi.list(1); // 申請書類テーブル
      if (applications) {
        currentApplications = applications.filter(app => app.承認状態 === '申請中');
        filterApplications();
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      currentApplications = tables[1]?.records?.filter(app => app.承認状態 === '申請中') || [];
      filterApplications();
    }
  }

  // 初期データ読み込み
  loadApplications();

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", filterApplications);

  // フィルター変更時の自動検索
  container.querySelector("#filter-urgency").addEventListener("change", filterApplications);
  container.querySelector("#filter-document-type").addEventListener("change", filterApplications);
  container.querySelector("#input-search").addEventListener("input", filterApplications);

  // 更新ボタン
  container.querySelector("#btn-refresh").addEventListener("click", loadApplications);

  // CSVエクスポート
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // 進捗監視画面への遷移
  container.querySelector("#btn-progress-monitor").addEventListener("click", () => {
    window.showScreen("scr-1779345940460");
  });

  // 全選択チェックボックス
  container.querySelector("#select-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".row-checkbox");
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedIds.add(cb.dataset.id);
      } else {
        selectedIds.delete(cb.dataset.id);
      }
    });
    container.querySelector("#btn-bulk-approve").disabled = selectedIds.size === 0;
  });

  // 一括承認ボタン
  container.querySelector("#btn-bulk-approve").addEventListener("click", async () => {
    if (selectedIds.size === 0) return;

    if (!confirm(`選択した${selectedIds.size}件の案件を一括承認しますか？`)) return;

    try {
      for (const id of selectedIds) {
        await processApproval(id, '承認', '一括承認');
      }
      selectedIds.clear();
      container.querySelector("#select-all").checked = false;
      container.querySelector("#btn-bulk-approve").disabled = true;
    } catch (error) {
      console.error('一括承認エラー:', error);
      alert('一括承認中にエラーが発生しました。');
    }
  });

  // モーダル関連のイベント
  container.querySelector("#close-modal").addEventListener("click", () => {
    container.querySelector("#approval-modal").style.display = 'none';
  });

  container.querySelector("#btn-approve").addEventListener("click", () => {
    const applicationId = container.querySelector("#approval-modal").dataset.applicationId;
    const comment = container.querySelector("#approval-comment").value;
    processApproval(applicationId, '承認', comment);
  });

  container.querySelector("#btn-reject").addEventListener("click", () => {
    const applicationId = container.querySelector("#approval-modal").dataset.applicationId;
    const comment = container.querySelector("#approval-comment").value;
    if (!comment.trim()) {
      alert('差戻し理由を入力してください。');
      return;
    }
    processApproval(applicationId, '差戻し', comment);
  });

  container.querySelector("#btn-hold").addEventListener("click", () => {
    const applicationId = container.querySelector("#approval-modal").dataset.applicationId;
    const comment = container.querySelector("#approval-comment").value;
    processApproval(applicationId, '保留', comment);
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const approveBtn = e.target.closest(".approve-btn");
    const rowCheckbox = e.target.closest(".row-checkbox");

    if (detailBtn) {
      const applicationId = detailBtn.dataset.id;
      window.showScreen("scr-1779349647621"); // 申請書類確認画面
    }

    if (approveBtn) {
      const applicationId = approveBtn.dataset.id;
      showApprovalModal(applicationId);
    }

    if (rowCheckbox) {
      const id = rowCheckbox.dataset.id;
      if (rowCheckbox.checked) {
        selectedIds.add(id);
      } else {
        selectedIds.delete(id);
        container.querySelector("#select-all").checked = false;
      }
      container.querySelector("#btn-bulk-approve").disabled = selectedIds.size === 0;
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector("#approval-modal").addEventListener("click", (e) => {
    if (e.target.id === "approval-modal") {
      container.querySelector("#approval-modal").style.display = 'none';
    }
  });
}

function(container, apiUrl, tables) {
  // URLパラメータから申請書類IDを取得
  const urlParams = new URLSearchParams(window.location.search);
  const applicationId = urlParams.get('id') || (tables[1] && tables[1].records && tables[1].records[0] ? tables[1].records[0].申請書類ID : null);

  // 承認フロー進捗テーブルの再描画関数
  function renderApprovalFlow(steps) {
    const tbody = container.querySelector('#approval-flow-tbody');
    if (!steps || steps.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align: center; color: var(--text-muted); font-size: 12px;">承認フローデータがありません</td></tr>';
      return;
    }

    tbody.innerHTML = steps.map(step => {
      const statusBadge = getStatusBadge(step.承認状態 || '未承認');
      const deadline = step.期限日時 ? new Date(step.期限日時).toLocaleString('ja-JP') : '-';
      const processedDate = step.承認日時 ? new Date(step.承認日時).toLocaleString('ja-JP') : '-';

      return `
        <tr data-id="${step.承認ステップID}">
          <td>${step.ステップ番号 || '-'}</td>
          <td>${step.承認者名 || '-'}</td>
          <td>${statusBadge}</td>
          <td>${deadline}</td>
          <td>${processedDate}</td>
        </tr>
      `;
    }).join('');
  }

  // 承認履歴テーブルの再描画関数
  function renderApprovalHistory(history) {
    const tbody = container.querySelector('#approval-history-tbody');
    if (!history || history.length === 0) {
      tbody.innerHTML = '<tr><td colspan="4" style="text-align: center; color: var(--text-muted); font-size: 12px;">承認履歴がありません</td></tr>';
      return;
    }

    tbody.innerHTML = history.map(record => {
      const processedDate = record.承認日時 ? new Date(record.承認日時).toLocaleString('ja-JP') : '-';
      const resultBadge = getResultBadge(record.承認結果 || '未処理');

      return `
        <tr data-id="${record.承認履歴ID}">
          <td>${processedDate}</td>
          <td>${record.承認者名 || '-'}</td>
          <td>${resultBadge}</td>
          <td style="max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${record.承認コメント || '-'}</td>
        </tr>
      `;
    }).join('');
  }

  // ステータスバッジの生成
  function getStatusBadge(status) {
    const colors = {
      '未承認': '#6b7280',
      '承認済': '#10b981',
      '否認': '#ef4444',
      '保留': '#f59e0b',
      'スキップ': '#8b5cf6'
    };
    const color = colors[status] || '#6b7280';
    return `<span style="background: ${color}; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">${status}</span>`;
  }

  // 処理結果バッジの生成
  function getResultBadge(result) {
    const colors = {
      '承認': '#10b981',
      '却下': '#ef4444',
      '差戻し': '#f59e0b',
      '保留': '#6b7280',
      '未処理': '#9ca3af'
    };
    const color = colors[result] || '#6b7280';
    return `<span style="background: ${color}; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">${result}</span>`;
  }

  // 緊急度バッジの生成
  function getEmergencyBadge(isEmergency) {
    if (isEmergency) {
      return '<span style="background: #ef4444; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">緊急</span>';
    }
    return '<span style="background: #6b7280; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">通常</span>';
  }

  // 添付ファイル一覧の表示
  function renderAttachments(hasAttachment, applicationId) {
    const attachmentList = container.querySelector('#attachment-list');

    if (!hasAttachment) {
      attachmentList.innerHTML = '<div style="font-size: 12px; color: var(--text-muted);">添付ファイルはありません</div>';
      return;
    }

    // サンプルの添付ファイル（実際の実装では API から取得）
    const sampleFiles = [
      { name: '申請書.pdf', size: '245KB', type: 'PDF' },
      { name: '見積書.xlsx', size: '128KB', type: 'Excel' }
    ];

    attachmentList.innerHTML = sampleFiles.map(file => `
      <div style="display: flex; align-items: center; justify-content: space-between; padding: 8px; background: rgba(0,0,0,0.25); border-radius: 6px; border: 1px solid rgba(255,255,255,0.18);">
        <div style="display: flex; align-items: center; gap: 8px;">
          <div style="background: var(--primary); color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 10px; font-weight: 500;">${file.type}</div>
          <span style="font-size: 13px; color: var(--text);">${file.name}</span>
          <span style="font-size: 11px; color: var(--text-muted);">(${file.size})</span>
        </div>
        <div style="display: flex; gap: 6px;">
          <button class="action-btn secondary" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">プレビュー</button>
          <button class="action-btn secondary" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">ダウンロード</button>
        </div>
      </div>
    `).join('');
  }

  // 申請書類詳細情報の表示
  function displayApplicationDetails(application, applicant, documentType) {
    container.querySelector('#application-id').textContent = application.申請書類ID || '-';
    container.querySelector('#application-title').textContent = application.申請タイトル || '-';
    container.querySelector('#emergency-status').innerHTML = getEmergencyBadge(application.緊急フラグ);
    container.querySelector('#applicant-name').textContent = applicant ? applicant.氏名 : '-';
    container.querySelector('#document-type').textContent = documentType ? documentType.文書種別名 : '-';
    container.querySelector('#application-date').textContent = application.作成日時 ? new Date(application.作成日時).toLocaleString('ja-JP') : '-';

    container.querySelector('#application-amount').textContent = application.申請金額 ? `¥${application.申請金額.toLocaleString()}` : '-';

    const startDate = application.申請開始日 ? new Date(application.申請開始日).toLocaleDateString('ja-JP') : '';
    const endDate = application.申請終了日 ? new Date(application.申請終了日).toLocaleDateString('ja-JP') : '';
    const period = startDate && endDate ? `${startDate} ～ ${endDate}` : (startDate || endDate || '-');
    container.querySelector('#application-period').textContent = period;

    container.querySelector('#application-content').textContent = application.申請内容 || '-';

    // 現在の承認状況
    const statusBadge = getStatusBadge(application.承認状態 || '申請中');
    container.querySelector('#current-step').textContent = `${application.承認段階 || 1}次承認`;
    container.querySelector('#approval-status').innerHTML = statusBadge;

    // 現在承認者の取得
    if (application.現在承認者ID && tables[0] && tables[0].records) {
      const currentApprover = tables[0].records.find(user => user.ユーザーID === application.現在承認者ID);
      container.querySelector('#current-approver').textContent = currentApprover ? currentApprover.氏名 : '-';
    } else {
      container.querySelector('#current-approver').textContent = '-';
    }

    // 添付ファイル表示
    renderAttachments(application.添付ファイル有無, application.申請書類ID);
  }

  // 初期データの読み込みと表示
  async function loadApplicationData() {
    if (!applicationId) {
      console.warn('申請書類IDが指定されていません');
      return;
    }

    try {
      // 申請書類データの取得
      const applications = await window.aivicApi.list(1); // 申請書類テーブル
      const application = applications ? applications.find(app => app.申請書類ID === applicationId) : null;

      if (!application) {
        console.warn('指定された申請書類が見つかりません');
        return;
      }

      // 関連データの取得
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      const documentTypes = await window.aivicApi.list(2); // 文書種別マスタ
      const approvalSteps = await window.aivicApi.list(4); // 承認ステップ
      const approvalHistory = await window.aivicApi.list(5); // 承認履歴

      // 申請者情報の取得
      const applicant = users ? users.find(user => user.ユーザーID === application.申請者ID) : null;

      // 文書種別情報の取得
      const documentType = documentTypes ? documentTypes.find(type => type.文書種別ID === application.申請種別) : null;

      // 申請書類詳細の表示
      displayApplicationDetails(application, applicant, documentType);

      // 承認フロー進捗の表示
      const currentSteps = approvalSteps ? approvalSteps.filter(step => step.申請書類ID === applicationId) : [];
      if (currentSteps.length > 0 && users) {
        // 承認者名を付与
        currentSteps.forEach(step => {
          const approver = users.find(user => user.ユーザーID === step.承認者ID);
          step.承認者名 = approver ? approver.氏名 : '不明';
        });
        currentSteps.sort((a, b) => (a.ステップ番号 || 0) - (b.ステップ番号 || 0));
      }
      renderApprovalFlow(currentSteps);

      // 承認履歴の表示
      const currentHistory = approvalHistory ? approvalHistory.filter(history => history.申請書類ID === applicationId) : [];
      if (currentHistory.length > 0 && users) {
        // 承認者名を付与
        currentHistory.forEach(history => {
          const approver = users.find(user => user.ユーザーID === history.承認者ID);
          history.承認者名 = approver ? approver.氏名 : '不明';
        });
        currentHistory.sort((a, b) => new Date(b.承認日時 || 0) - new Date(a.承認日時 || 0));
      }
      renderApprovalHistory(currentHistory);

    } catch (error) {
      console.error('データの読み込みに失敗しました:', error);
    }
  }

  // 承認判断入力画面への遷移
  container.querySelector('#btn-approval-decision').addEventListener('click', () => {
    window.showScreen('scr-1779349659638');
  });

  // 初期データの読み込み
  loadApplicationData();
}

function(container, apiUrl, tables) {
  // 承認履歴テーブルの再描画関数
  function renderApprovalHistory(histories) {
    const tbody = container.querySelector("#approval-history-tbody");
    if (!tbody) return;

    tbody.innerHTML = histories.map(h => {
      let statusBadge = '';
      if (h.承認結果 === '承認') {
        statusBadge = '<span style="background: rgba(34,197,94,0.15); color: #22c55e; padding: 2px 6px; border-radius: 4px; font-size: 11px;">承認</span>';
      } else if (h.承認結果 === '差戻し') {
        statusBadge = '<span style="background: rgba(239,68,68,0.15); color: #ef4444; padding: 2px 6px; border-radius: 4px; font-size: 11px;">差戻し</span>';
      } else if (h.承認結果 === '却下') {
        statusBadge = '<span style="background: rgba(107,114,128,0.15); color: #6b7280; padding: 2px 6px; border-radius: 4px; font-size: 11px;">却下</span>';
      }

      return `
        <tr data-id="${h.承認履歴ID}">
          <td style="padding: 6px 10px; font-size: 13px;">${h.承認者名 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${statusBadge}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${h.承認コメント || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px;">${h.承認日時 ? new Date(h.承認日時).toLocaleString('ja-JP') : ''}</td>
        </tr>
      `;
    }).join("");
  }

  // 初期データの表示
  if (tables[4] && tables[4].records) {
    renderApprovalHistory(tables[4].records);
  }

  // 判定結果の変更に応じて入力欄を切り替え
  const approvalResultSelect = container.querySelector("#approval-result");
  const approvalCommentSection = container.querySelector("#approval-comment-section");
  const rejectionReasonSection = container.querySelector("#rejection-reason-section");
  const denialReasonSection = container.querySelector("#denial-reason-section");
  const nextApproverSection = container.querySelector("#next-approver-section");

  if (approvalResultSelect) {
    approvalResultSelect.addEventListener("change", function() {
      const result = this.value;

      // 全セクションを非表示
      approvalCommentSection.style.display = "none";
      rejectionReasonSection.style.display = "none";
      denialReasonSection.style.display = "none";
      nextApproverSection.style.display = "none";

      // 選択に応じて表示
      if (result === "approved") {
        approvalCommentSection.style.display = "block";
        nextApproverSection.style.display = "block";
      } else if (result === "rejected") {
        rejectionReasonSection.style.display = "block";
      } else if (result === "denied") {
        denialReasonSection.style.display = "block";
      }
    });
  }

  // 判断確定ボタンのイベントリスナー
  const submitButton = container.querySelector("#btn-submit-approval");
  if (submitButton) {
    submitButton.addEventListener("click", async function() {
      const result = container.querySelector("#approval-result").value;
      if (!result) {
        alert("判定結果を選択してください。");
        return;
      }

      let comment = "";
      if (result === "approved") {
        comment = container.querySelector("#approval-comment").value;
        const nextApprover = container.querySelector("#next-approver").value;
        if (!nextApprover) {
          alert("次承認者を選択してください。");
          return;
        }
      } else if (result === "rejected") {
        comment = container.querySelector("#rejection-reason").value;
        if (!comment.trim()) {
          alert("差戻し理由を入力してください。");
          return;
        }
      } else if (result === "denied") {
        comment = container.querySelector("#denial-reason").value;
        if (!comment.trim()) {
          alert("却下理由を入力してください。");
          return;
        }
      }

      if (!confirm("承認判断を確定しますか？")) {
        return;
      }

      // 承認履歴に新しいレコードを追加
      const newHistory = {
        申請書類ID: "app-001", // 実際の申請書類IDを使用
        承認ステップID: "step-002",
        承認者ID: "current-user-id",
        承認者名: "現在のユーザー名",
        承認結果: result === "approved" ? "承認" : result === "rejected" ? "差戻し" : "却下",
        承認コメント: comment,
        承認日時: new Date().toISOString(),
        次承認者ID: result === "approved" ? container.querySelector("#next-approver").value : null,
        処理順序: 2
      };

      const saved = await window.aivicApi.save(4, newHistory); // 承認履歴テーブル
      if (saved) {
        alert("承認判断を確定しました。");
        // 結果通知処理画面に遷移
        window.showScreen("scr-1779349669424");
      }
    });
  }

  // 最新の承認履歴を取得して表示
  window.aivicApi.list(4).then(histories => {
    if (histories) {
      renderApprovalHistory(histories);
    }
  });
}

function(container, apiUrl, tables) {
  let selectedApplications = new Set();

  // 申請一覧の再描画関数
  function renderApplications(applications) {
    const tbody = container.querySelector("#application-tbody");
    tbody.innerHTML = applications.map(app => {
      const statusBadge = getStatusBadge(app.承認状態);
      const notificationStatus = getNotificationStatus(app.申請書類ID);
      return `
        <tr data-id="${app.申請書類ID}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px;">
            <input type="checkbox" class="app-checkbox" data-id="${app.申請書類ID}" style="accent-color: var(--primary);">
          </td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${app.申請書類ID || ""}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${app.申請者名 || ""}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${app.申請種別 || ""}</td>
          <td style="padding: 6px 10px;">${statusBadge}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${formatDateTime(app.最終承認日時)}</td>
          <td style="padding: 6px 10px;">${notificationStatus}</td>
        </tr>
      `;
    }).join("");
  }

  // 通知履歴の再描画関数
  function renderNotificationHistory(notifications) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = notifications.map(notif => {
      const statusBadge = getNotificationStatusBadge(notif.送信状態);
      const readStatus = notif.既読フラグ ? 
        '<span style="color: #4ade80; font-size: 11px;">既読</span>' : 
        '<span style="color: var(--text-muted); font-size: 11px;">未読</span>';

      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${formatDateTime(notif.送信日時)}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${notif.申請書類ID || ""}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${notif.通知先ユーザー名 || ""}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${notif.通知種別 || ""}</td>
          <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${notif.送信方法 || ""}</td>
          <td style="padding: 6px 10px;">${statusBadge}</td>
          <td style="padding: 6px 10px;">${readStatus}</td>
        </tr>
      `;
    }).join("");
  }

  // ステータスバッジ生成
  function getStatusBadge(status) {
    const colors = {
      '承認済': { bg: '#065f46', text: '#d1fae5' },
      '却下': { bg: '#991b1b', text: '#fecaca' },
      '差戻し': { bg: '#92400e', text: '#fed7aa' }
    };
    const color = colors[status] || { bg: '#374151', text: '#d1d5db' };
    return `<span style="background: ${color.bg}; color: ${color.text}; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">${status || ""}</span>`;
  }

  // 通知状態バッジ生成
  function getNotificationStatusBadge(status) {
    const colors = {
      '送信完了': { bg: '#065f46', text: '#d1fae5' },
      '送信失敗': { bg: '#991b1b', text: '#fecaca' },
      '送信待ち': { bg: '#92400e', text: '#fed7aa' }
    };
    const color = colors[status] || { bg: '#374151', text: '#d1d5db' };
    return `<span style="background: ${color.bg}; color: ${color.text}; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">${status || ""}</span>`;
  }

  // 通知状況取得
  function getNotificationStatus(applicationId) {
    // 通知履歴から該当申請の最新通知状況を取得
    const notifications = tables[6]?.records || [];
    const appNotifications = notifications.filter(n => n.申請書類ID === applicationId);
    if (appNotifications.length === 0) {
      return '<span style="color: var(--text-muted); font-size: 11px;">未送信</span>';
    }
    const latest = appNotifications.sort((a, b) => new Date(b.送信日時) - new Date(a.送信日時))[0];
    return getNotificationStatusBadge(latest.送信状態);
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return "";
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', { 
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit'
    });
  }

  // 通知プレビュー更新
  function updateNotificationPreview() {
    const template = container.querySelector("#notification-template").value;
    const preview = container.querySelector("#notification-preview");

    const templates = {
      'approval': `件名: 申請が承認されました\n\n申請書類番号: {申請書類番号}\n申請種別: {申請種別}\n\nご申請いただいた書類の承認が完了いたしました。\n詳細はシステムにてご確認ください。`,
      'rejection': `件名: 申請が却下されました\n\n申請書類番号: {申請書類番号}\n申請種別: {申請種別}\n\nご申請いただいた書類は却下となりました。\n却下理由をご確認の上、必要に応じて再申請をお願いいたします。`,
      'return': `件名: 申請が差戻しされました\n\n申請書類番号: {申請書類番号}\n申請種別: {申請種別}\n\nご申請いただいた書類は差戻しとなりました。\n修正後、再度申請をお願いいたします。`
    };

    if (template && templates[template]) {
      preview.innerHTML = templates[template].replace(/\n/g, '<br>');
    } else {
      preview.innerHTML = 'テンプレートを選択すると通知内容のプレビューが表示されます';
    }
  }

  // CSVエクスポート
  function exportNotificationHistoryCSV() {
    window.aivicApi.list(6).then(notifications => {
      if (!notifications) return;

      const headers = ['送信日時', '申請書類ID', '通知先ユーザーID', '通知種別', '通知タイトル', '送信方法', '送信状態', '既読フラグ'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...notifications.map(row => [
          row.送信日時 || '',
          row.申請書類ID || '',
          row.通知先ユーザーID || '',
          row.通知種別 || '',
          row.通知タイトル || '',
          row.送信方法 || '',
          row.送信状態 || '',
          row.既読フラグ ? '既読' : '未読'
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `通知履歴_${new Date().toISOString().slice(0,10)}.csv`;
      link.click();
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(1).then(applications => {
    if (applications) renderApplications(applications);
  });

  window.aivicApi.list(6).then(notifications => {
    if (notifications) renderNotificationHistory(notifications);
  });

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const statusFilter = container.querySelector("#status-filter").value;
    const docTypeFilter = container.querySelector("#doc-type-filter").value;

    window.aivicApi.list(1).then(applications => {
      if (!applications) return;

      const filtered = applications.filter(app => {
        const matchKeyword = !keyword || 
          (app.申請書類ID && app.申請書類ID.toLowerCase().includes(keyword)) ||
          (app.申請者名 && app.申請者名.toLowerCase().includes(keyword));
        const matchStatus = !statusFilter || app.承認状態 === statusFilter;
        const matchDocType = !docTypeFilter || app.申請種別 === docTypeFilter;

        return matchKeyword && matchStatus && matchDocType;
      });

      renderApplications(filtered);
    });
  });

  // チェックボックス選択管理
  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("app-checkbox")) {
      const appId = e.target.dataset.id;
      if (e.target.checked) {
        selectedApplications.add(appId);
      } else {
        selectedApplications.delete(appId);
      }
    }
  });

  // プレビュー更新
  container.querySelector("#btn-preview").addEventListener("click", updateNotificationPreview);
  container.querySelector("#notification-template").addEventListener("change", updateNotificationPreview);

  // 通知送信
  container.querySelector("#btn-send-notification").addEventListener("click", async () => {
    if (selectedApplications.size === 0) {
      alert("通知を送信する申請を選択してください。");
      return;
    }

    const template = container.querySelector("#notification-template").value;
    if (!template) {
      alert("通知テンプレートを選択してください。");
      return;
    }

    const notifyEmail = container.querySelector("#notify-email").checked;
    const notifySystem = container.querySelector("#notify-system").checked;

    if (!notifyEmail && !notifySystem) {
      alert("通知方法を選択してください。");
      return;
    }

    // 選択された申請に対して通知履歴を作成
    for (const appId of selectedApplications) {
      const methods = [];
      if (notifyEmail) methods.push("メール");
      if (notifySystem) methods.push("システム内通知");

      for (const method of methods) {
        const notification = {
          申請書類ID: appId,
          通知先ユーザーID: "user-" + Math.random().toString(36).substr(2, 9),
          通知種別: template === 'approval' ? '承認完了' : template === 'rejection' ? '却下' : '差戻し',
          通知タイトル: template === 'approval' ? '申請が承認されました' : template === 'rejection' ? '申請が却下されました' : '申請が差戻しされました',
          通知内容: `申請書類番号: ${appId}の処理が完了しました。`,
          送信方法: method,
          送信状態: "送信完了",
          送信日時: new Date().toISOString(),
          既読フラグ: false,
          再送回数: 0
        };

        await window.aivicApi.save(6, notification);
      }
    }

    selectedApplications.clear();

    // チェックボックスをクリア
    container.querySelectorAll(".app-checkbox").forEach(cb => cb.checked = false);

    // 履歴を再読み込み
    window.aivicApi.list(6).then(notifications => {
      if (notifications) renderNotificationHistory(notifications);
    });

    alert("通知を送信しました。");
  });

  // CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", exportNotificationHistoryCSV);
}

function(container, apiUrl, tables) {
  let currentSteps = [];
  let editingStepIndex = -1;
  let selectedApplicationId = null;

  // 承認ステップテーブル再描画
  function renderSteps(steps) {
    const tbody = container.querySelector("#steps-tbody");
    tbody.innerHTML = steps.map((step, index) => `
      <tr data-index="${index}">
        <td style="text-align: center;">
          <div style="display: flex; gap: 4px; justify-content: center;">
            <button class="action-btn secondary move-up-btn" data-index="${index}" style="padding: 2px 6px; font-size: 11px;" ${index === 0 ? 'disabled' : ''}>↑</button>
            <span style="font-weight: 500;">${index + 1}</span>
            <button class="action-btn secondary move-down-btn" data-index="${index}" style="padding: 2px 6px; font-size: 11px;" ${index === steps.length - 1 ? 'disabled' : ''}>↓</button>
          </div>
        </td>
        <td>${step.approverName || step.approver || ''}</td>
        <td style="text-align: center;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${step.required ? 'background: rgba(255, 100, 100, 0.2); color: #ff6464;' : 'background: rgba(100, 255, 100, 0.2); color: #64ff64;'}">${step.required ? '必須' : '任意'}</span>
        </td>
        <td style="text-align: center;">
          <span style="font-size: 12px;">${step.processType === 'parallel' ? '並列' : '直列'}</span>
        </td>
        <td style="text-align: center;">${step.deadline || 3}</td>
        <td>
          <div style="display: flex; gap: 4px;">
            <button class="action-btn secondary edit-step-btn" data-index="${index}" style="padding: 4px 8px; font-size: 11px;">編集</button>
            <button class="action-btn secondary delete-step-btn" data-index="${index}" style="padding: 4px 8px; font-size: 11px;">削除</button>
          </div>
        </td>
      </tr>
    `).join("");
  }

  // 現在のルート情報表示
  function updateCurrentRouteInfo(applicationId) {
    const routeInfo = container.querySelector("#current-route-info");
    if (!applicationId) {
      routeInfo.innerHTML = "申請書類を選択してください";
      return;
    }

    // 申請書類情報を取得して表示
    const application = tables[1]?.records?.find(r => r.id === applicationId);
    if (application) {
      routeInfo.innerHTML = `
        <div style="display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 12px; font-size: 12px;">
          <div><strong>申請種別:</strong> ${application.申請種別 || application.documentType || '経費申請'}</div>
          <div><strong>申請者:</strong> ${application.申請者名 || application.applicantName || '山田太郎'}</div>
          <div><strong>現在段階:</strong> ${application.承認段階 || application.currentStep || 1}次承認</div>
        </div>
        <div style="margin-top: 8px; font-size: 12px;">
          <strong>承認状態:</strong> ${application.承認状態 || application.approvalStatus || '承認中'}
        </div>
      `;
    }
  }

  // フォームモーダルの表示/非表示
  function showStepForm(stepIndex = -1) {
    const modal = container.querySelector("#step-form-modal");
    editingStepIndex = stepIndex;

    if (stepIndex >= 0) {
      const step = currentSteps[stepIndex];
      container.querySelector("#select-approver").value = step.approver || '';
      container.querySelector("#input-deadline").value = step.deadline || 3;
      container.querySelector("#select-escalation").value = step.escalation || '';
      container.querySelector("#check-required").checked = step.required !== false;
      container.querySelector("#textarea-note").value = step.note || '';
      const processType = step.processType || 'serial';
      container.querySelector(`input[name="process-type"][value="${processType}"]`).checked = true;
    } else {
      // 新規追加時はフォームをクリア
      container.querySelector("#select-approver").value = '';
      container.querySelector("#input-deadline").value = 3;
      container.querySelector("#select-escalation").value = '';
      container.querySelector("#check-required").checked = true;
      container.querySelector("#textarea-note").value = '';
      container.querySelector('input[name="process-type"][value="serial"]').checked = true;
    }

    modal.style.display = "block";
  }

  function hideStepForm() {
    container.querySelector("#step-form-modal").style.display = "none";
    editingStepIndex = -1;
  }

  // 初期データ読み込み
  renderSteps(currentSteps);

  // 今日の日付を初期値に設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector("#input-start-date").value = today;

  // 申請書類選択イベント
  container.querySelector("#select-application").addEventListener("change", (e) => {
    selectedApplicationId = e.target.value;
    updateCurrentRouteInfo(selectedApplicationId);
  });

  // 処理ルート読込ボタン
  container.querySelector("#btn-load-route").addEventListener("click", async () => {
    if (!selectedApplicationId) {
      alert("申請書類を選択してください");
      return;
    }

    // 承認フロー定義から現在のステップを読み込み
    const flowDefinitions = await window.aivicApi.list(3); // 承認フロー定義テーブル
    if (flowDefinitions) {
      const applicationFlows = flowDefinitions.filter(f => f.申請書類ID === selectedApplicationId || f.documentId === selectedApplicationId);
      currentSteps = applicationFlows.map(f => ({
        approver: f.承認者ID || f.approverId,
        approverName: f.承認者名 || f.approverName || '承認者',
        required: f.必須承認フラグ !== false,
        processType: f.並列承認フラグ ? 'parallel' : 'serial',
        deadline: f.承認期限日数 || f.deadlineDays || 3,
        escalation: f.エスカレーション先ID || f.escalationId,
        note: f.備考 || f.note || ''
      }));
      renderSteps(currentSteps);
    }
  });

  // ステップ追加ボタン
  container.querySelector("#btn-add-step").addEventListener("click", () => {
    showStepForm();
  });

  // ステップ保存ボタン
  container.querySelector("#btn-save-step").addEventListener("click", () => {
    const approver = container.querySelector("#select-approver").value;
    const approverName = container.querySelector("#select-approver").selectedOptions[0]?.text || '';
    const deadline = parseInt(container.querySelector("#input-deadline").value) || 3;
    const escalation = container.querySelector("#select-escalation").value;
    const required = container.querySelector("#check-required").checked;
    const processType = container.querySelector('input[name="process-type"]:checked').value;
    const note = container.querySelector("#textarea-note").value;

    if (!approver) {
      alert("承認者を選択してください");
      return;
    }

    const stepData = {
      approver,
      approverName,
      deadline,
      escalation,
      required,
      processType,
      note
    };

    if (editingStepIndex >= 0) {
      currentSteps[editingStepIndex] = stepData;
    } else {
      currentSteps.push(stepData);
    }

    renderSteps(currentSteps);
    hideStepForm();
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel-step").addEventListener("click", hideStepForm);

  // イベントデリゲーション（編集・削除・移動）
  container.addEventListener("click", (e) => {
    const editBtn = e.target.closest(".edit-step-btn");
    const deleteBtn = e.target.closest(".delete-step-btn");
    const moveUpBtn = e.target.closest(".move-up-btn");
    const moveDownBtn = e.target.closest(".move-down-btn");

    if (editBtn) {
      const index = parseInt(editBtn.dataset.index);
      showStepForm(index);
    }

    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.index);
      if (confirm("このステップを削除しますか？")) {
        currentSteps.splice(index, 1);
        renderSteps(currentSteps);
      }
    }

    if (moveUpBtn && !moveUpBtn.disabled) {
      const index = parseInt(moveUpBtn.dataset.index);
      if (index > 0) {
        [currentSteps[index - 1], currentSteps[index]] = [currentSteps[index], currentSteps[index - 1]];
        renderSteps(currentSteps);
      }
    }

    if (moveDownBtn && !moveDownBtn.disabled) {
      const index = parseInt(moveDownBtn.dataset.index);
      if (index < currentSteps.length - 1) {
        [currentSteps[index], currentSteps[index + 1]] = [currentSteps[index + 1], currentSteps[index]];
        renderSteps(currentSteps);
      }
    }
  });

  // 変更プレビューボタン
  container.querySelector("#btn-preview").addEventListener("click", () => {
    if (!selectedApplicationId) {
      alert("申請書類を選択してください");
      return;
    }

    const changeReason = container.querySelector("#textarea-change-reason").value;
    if (!changeReason.trim()) {
      alert("変更理由を入力してください");
      return;
    }

    let previewText = "=== 処理ルート変更プレビュー ===\n\n";
    previewText += `申請書類ID: ${selectedApplicationId}\n`;
    previewText += `変更理由: ${changeReason}\n\n`;
    previewText += "新しい承認ステップ:\n";

    currentSteps.forEach((step, index) => {
      previewText += `${index + 1}. ${step.approverName} (${step.required ? '必須' : '任意'}, ${step.processType === 'parallel' ? '並列' : '直列'}, ${step.deadline}日)\n`;
    });

    alert(previewText);
  });

  // 処理ルート更新ボタン
  container.querySelector("#btn-update-route").addEventListener("click", async () => {
    if (!selectedApplicationId) {
      alert("申請書類を選択してください");
      return;
    }

    const changeReason = container.querySelector("#textarea-change-reason").value;
    const changeType = container.querySelector("#select-change-type").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;

    if (!changeReason.trim()) {
      alert("変更理由を入力してください");
      return;
    }

    if (!changeType) {
      alert("変更種別を選択してください");
      return;
    }

    if (!confirm("処理ルートを更新しますか？")) {
      return;
    }

    try {
      // 処理ルート変更履歴を保存
      const changeHistory = {
        申請書類ID: selectedApplicationId,
        変更種別: changeType,
        変更理由: changeReason,
        変更内容: JSON.stringify(currentSteps),
        変更実行者ID: 'current-user-id',
        変更日時: new Date().toISOString(),
        有効フラグ: true
      };

      const savedHistory = await window.aivicApi.save(8, changeHistory); // 処理ルート変更履歴テーブル

      if (savedHistory) {
        // 承認フロー定義を更新
        for (let i = 0; i < currentSteps.length; i++) {
          const step = currentSteps[i];
          const flowDefinition = {
            文書種別ID: selectedApplicationId,
            承認フロー名: `更新されたフロー_${Date.now()}`,
            承認ステップ番号: i + 1,
            承認者ID: step.approver,
            承認者役職: step.approverName,
            必須承認フラグ: step.required,
            並列承認フラグ: step.processType === 'parallel',
            承認期限日数: step.deadline,
            エスカレーション先ID: step.escalation,
            有効開始日: startDate ? new Date(startDate).toISOString() : new Date().toISOString(),
            有効終了日: endDate ? new Date(endDate).toISOString() : null,
            備考: step.note,
            作成者ID: 'current-user-id',
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          };

          await window.aivicApi.save(3, flowDefinition); // 承認フロー定義テーブル
        }

        alert("処理ルートが正常に更新されました");

        // フォームをクリア
        container.querySelector("#textarea-change-reason").value = '';
        container.querySelector("#select-change-type").value = '';
        container.querySelector("#input-end-date").value = '';
        currentSteps = [];
        renderSteps(currentSteps);
        updateCurrentRouteInfo(null);
        container.querySelector("#select-application").value = '';
        selectedApplicationId = null;
      }
    } catch (error) {
      console.error("処理ルート更新エラー:", error);
      alert("処理ルートの更新に失敗しました");
    }
  });
}

function(container, apiUrl, tables) {
  let currentFile = null;
  let currentDetection = null;
  let changeHistory = [];

  // DOM要素の取得
  const uploadArea = container.querySelector('#upload-area');
  const fileInput = container.querySelector('#file-input');
  const uploadPlaceholder = container.querySelector('#upload-placeholder');
  const uploadProgress = container.querySelector('#upload-progress');
  const progressBar = container.querySelector('#progress-bar');
  const detectionResult = container.querySelector('#detection-result');
  const autoDetection = container.querySelector('#auto-detection');
  const confidenceBar = container.querySelector('#confidence-bar');
  const confidenceText = container.querySelector('#confidence-text');
  const manualDocumentType = container.querySelector('#manual-document-type');
  const detectionReason = container.querySelector('#detection-reason');
  const approvalFlow = container.querySelector('#approval-flow');
  const flowSteps = container.querySelector('#flow-steps');
  const documentPreview = container.querySelector('#document-preview');
  const changeHistoryDiv = container.querySelector('#change-history');
  const errorMessage = container.querySelector('#error-message');

  // ボタン要素
  const btnDetect = container.querySelector('#btn-detect');
  const btnReDetect = container.querySelector('#btn-re-detect');
  const btnConfirmFlow = container.querySelector('#btn-confirm-flow');
  const btnFinalize = container.querySelector('#btn-finalize');
  const btnProcess = container.querySelector('#btn-process');

  // 文書種別マスタデータ（テーブルから取得）
  const documentTypes = tables[2]?.records || [
    { id: '1', 文書種別コード: 'vacation-request', 文書種別名: '休暇申請書', 承認段数: 2 },
    { id: '2', 文書種別コード: 'expense-report', 文書種別名: '経費精算書', 承認段数: 3 },
    { id: '3', 文書種別コード: 'business-proposal', 文書種別名: '稟議書', 承認段数: 4 },
    { id: '4', 文書種別コード: 'overtime-request', 文書種別名: '残業申請書', 承認段数: 1 },
    { id: '5', 文書種別コード: 'purchase-request', 文書種別名: '購買申請書', 承認段数: 3 },
    { id: '6', 文書種別コード: 'travel-request', 文書種別名: '出張申請書', 承認段数: 2 }
  ];

  // エラーメッセージ表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  // 変更履歴を追加
  function addChangeHistory(action, details) {
    const timestamp = new Date().toLocaleString('ja-JP');
    changeHistory.unshift({ timestamp, action, details });
    renderChangeHistory();
  }

  // 変更履歴を描画
  function renderChangeHistory() {
    if (changeHistory.length === 0) {
      changeHistoryDiv.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px;">履歴はありません</div>';
      return;
    }

    changeHistoryDiv.innerHTML = changeHistory.map(h => `
      <div style="border-bottom: 1px solid rgba(255,255,255,0.08); padding: 8px 0; font-size: 11px;">
        <div style="color: var(--text); font-weight: 500;">${h.action}</div>
        <div style="color: var(--text-muted); margin: 2px 0;">${h.details}</div>
        <div style="color: var(--text-muted);">${h.timestamp}</div>
      </div>
    `).join('');
  }

  // ファイルアップロード処理
  function handleFileUpload(file) {
    if (!file) return;

    currentFile = file;
    uploadPlaceholder.style.display = 'none';
    uploadProgress.style.display = 'block';

    // プログレスバーアニメーション
    let progress = 0;
    const interval = setInterval(() => {
      progress += Math.random() * 20;
      if (progress >= 100) {
        progress = 100;
        clearInterval(interval);
        setTimeout(() => {
          uploadProgress.style.display = 'none';
          uploadPlaceholder.style.display = 'block';
          uploadPlaceholder.innerHTML = `
            <div style="font-size: 13px; color: var(--text); margin-bottom: 4px;">${file.name}</div>
            <div style="font-size: 11px; color: var(--text-muted);">ファイルサイズ: ${(file.size / 1024).toFixed(1)} KB</div>
          `;
          btnDetect.disabled = false;
          showDocumentPreview(file);
          addChangeHistory('ファイルアップロード', `${file.name} (${(file.size / 1024).toFixed(1)} KB)`);
        }, 500);
      }
      progressBar.style.width = progress + '%';
    }, 100);
  }

  // 文書プレビュー表示
  function showDocumentPreview(file) {
    if (file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (e) => {
        documentPreview.innerHTML = `<img src="${e.target.result}" style="max-width: 100%; max-height: 100%; object-fit: contain;">`;
      };
      reader.readAsDataURL(file);
    } else {
      documentPreview.innerHTML = `
        <div style="text-align: center;">
          <div style="font-size: 24px; margin-bottom: 8px;">📄</div>
          <div style="font-size: 12px; color: var(--text);">${file.name}</div>
          <div style="font-size: 11px; color: var(--text-muted); margin-top: 4px;">${file.type || 'Unknown'}</div>
        </div>
      `;
    }
  }

  // 文書種別判定処理
  function performDetection() {
    if (!currentFile) {
      showError('ファイルが選択されていません');
      return;
    }

    // 模擬的な判定処理
    const fileName = currentFile.name.toLowerCase();
    let detectedType = null;
    let confidence = 0;
    let reason = '';

    if (fileName.includes('休暇') || fileName.includes('vacation')) {
      detectedType = documentTypes.find(t => t.文書種別コード === 'vacation-request');
      confidence = 92;
      reason = 'ファイル名に「休暇」が含まれており、休暇申請書と判定しました。';
    } else if (fileName.includes('経費') || fileName.includes('expense')) {
      detectedType = documentTypes.find(t => t.文書種別コード === 'expense-report');
      confidence = 88;
      reason = 'ファイル名に「経費」が含まれており、経費精算書と判定しました。';
    } else if (fileName.includes('稟議') || fileName.includes('proposal')) {
      detectedType = documentTypes.find(t => t.文書種別コード === 'business-proposal');
      confidence = 85;
      reason = 'ファイル名に「稟議」が含まれており、稟議書と判定しました。';
    } else if (fileName.includes('残業') || fileName.includes('overtime')) {
      detectedType = documentTypes.find(t => t.文書種別コード === 'overtime-request');
      confidence = 90;
      reason = 'ファイル名に「残業」が含まれており、残業申請書と判定しました。';
    } else {
      detectedType = documentTypes[Math.floor(Math.random() * documentTypes.length)];
      confidence = 65;
      reason = 'ファイル名からの判定が困難なため、文書内容を解析して判定しました。';
    }

    currentDetection = {
      type: detectedType,
      confidence: confidence,
      reason: reason
    };

    // UI更新
    detectionResult.style.display = 'block';
    autoDetection.textContent = detectedType.文書種別名;
    confidenceBar.style.width = confidence + '%';
    confidenceText.textContent = confidence + '%';
    detectionReason.textContent = reason;
    manualDocumentType.value = detectedType.文書種別コード;

    // ボタン状態更新
    btnReDetect.disabled = false;
    btnConfirmFlow.disabled = false;
    btnFinalize.disabled = false;

    addChangeHistory('自動判定実行', `${detectedType.文書種別名} (信頼度: ${confidence}%)`);
    showApprovalFlow(detectedType);
  }

  // 承認フロー表示
  function showApprovalFlow(docType) {
    if (!docType) return;

    approvalFlow.style.display = 'block';
    const steps = [];
    for (let i = 1; i <= docType.承認段数; i++) {
      steps.push(`${i}次承認: 部門長${i > 1 ? `(${i}段階)` : ''}`);
    }
    flowSteps.innerHTML = steps.map((step, index) => `
      <div style="display: flex; align-items: center; margin-bottom: 4px;">
        <div style="width: 20px; height: 20px; border-radius: 50%; background: var(--primary); color: #fff; font-size: 10px; display: flex; align-items: center; justify-content: center; margin-right: 8px;">
          ${index + 1}
        </div>
        <span>${step}</span>
      </div>
    `).join('');
  }

  // イベントリスナー設定
  uploadArea.addEventListener('click', () => fileInput.click());

  uploadArea.addEventListener('dragover', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'var(--primary)';
  });

  uploadArea.addEventListener('dragleave', () => {
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  uploadArea.addEventListener('drop', (e) => {
    e.preventDefault();
    uploadArea.style.borderColor = 'rgba(255,255,255,0.18)';
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFileUpload(files[0]);
    }
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFileUpload(e.target.files[0]);
    }
  });

  btnDetect.addEventListener('click', performDetection);
  btnReDetect.addEventListener('click', performDetection);

  btnConfirmFlow.addEventListener('click', () => {
    const selectedType = manualDocumentType.value;
    if (selectedType) {
      const docType = documentTypes.find(t => t.文書種別コード === selectedType);
      showApprovalFlow(docType);
      addChangeHistory('承認フロー確認', `${docType.文書種別名}の承認フローを確認`);
    } else {
      showError('文書種別を選択してください');
    }
  });

  btnFinalize.addEventListener('click', async () => {
    if (!currentDetection && !manualDocumentType.value) {
      showError('文書種別が判定されていません');
      return;
    }

    const finalType = manualDocumentType.value || currentDetection.type.文書種別コード;
    const docType = documentTypes.find(t => t.文書種別コード === finalType);

    // 申請書類として保存
    const applicationData = {
      申請種別: docType.文書種別名,
      申請タイトル: currentFile.name,
      申請内容: `自動判定により${docType.文書種別名}として分類`,
      承認状態: '申請中',
      承認段階: 1,
      緊急フラグ: false,
      添付ファイル有無: true,
      申請者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, applicationData);
    if (saved) {
      addChangeHistory('判定結果確定', `${docType.文書種別名}として確定`);
      btnProcess.disabled = false;
    } else {
      showError('判定結果の保存に失敗しました');
    }
  });

  btnProcess.addEventListener('click', () => {
    window.showScreen("scr-1779346876884");
  });

  manualDocumentType.addEventListener('change', (e) => {
    if (e.target.value) {
      const docType = documentTypes.find(t => t.文書種別コード === e.target.value);
      showApprovalFlow(docType);
      btnConfirmFlow.disabled = false;
      btnFinalize.disabled = false;
      addChangeHistory('手動種別選択', `${docType.文書種別名}を手動選択`);
    }
  });

  // 初期化
  renderChangeHistory();
}

function(container, apiUrl, tables) {
  // 1. 履歴テーブル再描画関数
  function renderHistoryRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.判定日時 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.判定者 || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <span style="padding: 2px 6px; border-radius: 4px; font-size: 11px; ${r.判定結果 === '電子化可能' ? 'background: rgba(34, 197, 94, 0.15); color: #22c55e;' : r.判定結果 === '電子化不可' ? 'background: rgba(239, 68, 68, 0.15); color: #ef4444;' : 'background: rgba(251, 191, 36, 0.15); color: #fbbf24;'}">
            ${r.判定結果 || ""}
          </span>
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.処理ルート || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.OCR精度 || ""}%</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.判定理由 || ""}</td>
      </tr>
    `).join("");
  }

  // 2. 初期データ表示
  if (tables && tables[0] && tables[0].records) {
    renderHistoryRows(tables[0].records);
  }

  // サンプルデータで申請書類情報を設定
  container.querySelector("#application-id").value = "APP-2024-001234";
  container.querySelector("#applicant-name").value = "田中太郎";
  container.querySelector("#file-name").value = "経費申請書_202401.pdf";
  container.querySelector("#file-size").value = "2.4MB";
  container.querySelector("#file-format").value = "PDF";

  // 3. 手動オーバーライドチェックボックスの制御
  const manualOverride = container.querySelector("#manual-override");
  const judgmentReason = container.querySelector("#judgment-reason");
  const overallResult = container.querySelector("#overall-result");

  manualOverride.addEventListener("change", function() {
    if (this.checked) {
      judgmentReason.removeAttribute("readonly");
      judgmentReason.style.background = "rgba(0,0,0,0.4)";
      overallResult.textContent = "手動判定中";
      overallResult.style.background = "rgba(251, 191, 36, 0.15)";
      overallResult.style.color = "#fbbf24";
    } else {
      judgmentReason.setAttribute("readonly", "");
      judgmentReason.style.background = "rgba(0,0,0,0.25)";
      overallResult.textContent = "電子化可能";
      overallResult.style.background = "rgba(34, 197, 94, 0.15)";
      overallResult.style.color = "#22c55e";
    }
  });

  // 4. 処理ルート選択の制御
  const routeRadios = container.querySelectorAll('input[name="processing-route"]');
  const executeBtn = container.querySelector("#btn-execute-electronic");
  const sendPaperBtn = container.querySelector("#btn-send-paper");

  routeRadios.forEach(radio => {
    radio.addEventListener("change", function() {
      if (this.value === "electronic") {
        executeBtn.style.display = "inline-block";
        sendPaperBtn.style.display = "none";
      } else if (this.value === "paper") {
        executeBtn.style.display = "none";
        sendPaperBtn.style.display = "inline-block";
      } else {
        executeBtn.style.display = "inline-block";
        sendPaperBtn.style.display = "inline-block";
      }
    });
  });

  // 5. ボタンイベント
  container.querySelector("#btn-execute-electronic").addEventListener("click", async function() {
    const applicationId = container.querySelector("#application-id").value;
    const documentType = container.querySelector("#document-type").value;
    const processingRoute = container.querySelector('input[name="processing-route"]:checked').value;
    const reason = container.querySelector("#judgment-reason").value;

    if (!documentType) {
      alert("文書種別を選択してください");
      return;
    }

    const newRecord = {
      申請書類ID: applicationId,
      判定日時: new Date().toLocaleString("ja-JP"),
      判定者: "システム管理者",
      判定結果: "電子化可能",
      処理ルート: processingRoute === "electronic" ? "電子化処理" : processingRoute === "hybrid" ? "ハイブリッド処理" : "紙媒体処理",
      OCR精度: 94,
      判定理由: reason
    };

    const saved = await window.aivicApi.save(0, newRecord);
    if (saved) {
      alert("電子化処理を実行しました");
      const updatedRows = await window.aivicApi.list(0);
      if (updatedRows) renderHistoryRows(updatedRows);
    }
  });

  container.querySelector("#btn-send-paper").addEventListener("click", async function() {
    const applicationId = container.querySelector("#application-id").value;
    const reason = container.querySelector("#judgment-reason").value;

    const newRecord = {
      申請書類ID: applicationId,
      判定日時: new Date().toLocaleString("ja-JP"),
      判定者: "システム管理者",
      判定結果: "電子化不可",
      処理ルート: "紙媒体処理",
      OCR精度: 78,
      判定理由: reason || "OCR精度が基準値を下回るため紙媒体処理へ回送"
    };

    const saved = await window.aivicApi.save(0, newRecord);
    if (saved) {
      alert("紙媒体処理へ回送しました");
      const updatedRows = await window.aivicApi.list(0);
      if (updatedRows) renderHistoryRows(updatedRows);
    }
  });

  container.querySelector("#btn-document-classification").addEventListener("click", function() {
    window.showScreen("scr-1779350024410");
  });

  // 6. 最新データの読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) renderHistoryRows(rows);
  });
}

function(container, apiUrl, tables) {
  let currentSteps = [];
  let selectedApprover = null;
  let editingStepIndex = -1;

  // 承認ステップテーブル再描画
  function renderSteps() {
