        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">
          <input type="checkbox" ${step.parallel ? 'checked' : ''} class="parallel-checkbox" data-index="${index}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${step.escalationTarget || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">
          <button class="action-btn secondary edit-step-btn" data-index="${index}">編集</button>
          <button class="action-btn secondary delete-step-btn" data-index="${index}" style="margin-left: 4px;">削除</button>
        </td>
