      <tr>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">
          <input type="radio" name="approver-select" value="${approver.id}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${approver.name || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${approver.department || ""}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid var(--border);">${approver.role || ""}</td>
      </tr>
    `).join("");
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(users => {
    if (users) {
      const approvers = users.map(user => ({
        id: user.id,
        name: user.name || user.userName,
        department: user.department || "未設定",
        role: user.role || user.position || "一般"
      }));
      renderApprovers(approvers);
    }
  });

  // 承認フロー定義データの初期読み込み
  window.aivicApi.list(3).then(flows => {
    if (flows && flows.length > 0) {
      // 既存のフロー定義があれば表示
      const existingFlow = flows[0];
      if (existingFlow.documentTypeId) {
        container.querySelector("#document-type").value = existingFlow.documentTypeId;
      }
      if (existingFlow.approvalFlowName) {
        container.querySelector("#route-name").value = existingFlow.approvalFlowName;
      }
      if (existingFlow.approvalDeadlineDays) {
        container.querySelector("#approval-deadline").value = existingFlow.approvalDeadlineDays;
      }
    }
  });

  // ステップ追加ボタン
  container.querySelector("#add-step-btn").addEventListener("click", () => {
    editingStepIndex = -1;
    container.querySelector("#approver-modal").style.display = "block";
  });

  // モーダル閉じる
  container.querySelector("#close-modal-btn").addEventListener("click", () => {
    container.querySelector("#approver-modal").style.display = "none";
  });

  container.querySelector("#cancel-select-btn").addEventListener("click", () => {
    container.querySelector("#approver-modal").style.display = "none";
  });

  // 承認者選択確定
  container.querySelector("#confirm-select-btn").addEventListener("click", () => {
    const selectedRadio = container.querySelector('input[name="approver-select"]:checked');
    if (!selectedRadio) {
      alert("承認者を選択してください");
      return;
    }

    const approverId = selectedRadio.value;
    const approverRow = selectedRadio.closest("tr");
    const approverName = approverRow.cells[1].textContent;
    const approverRole = approverRow.cells[3].textContent;

    const newStep = {
      stepOrder: currentSteps.length + 1,
      approverId: approverId,
      approverName: approverName,
      approverRole: approverRole,
      required: true,
      parallel: false,
      escalationTarget: ""
    };

    if (editingStepIndex >= 0) {
      currentSteps[editingStepIndex] = { ...currentSteps[editingStepIndex], ...newStep };
    } else {
      currentSteps.push(newStep);
    }

    renderSteps();
    container.querySelector("#approver-modal").style.display = "none";
  });

  // 承認者検索
  container.querySelector("#approver-search").addEventListener("input", (e) => {
    const keyword = e.target.value.toLowerCase();
    window.aivicApi.list(0).then(users => {
      if (users) {
        const filtered = users.filter(user => 
          (user.name || user.userName || "").toLowerCase().includes(keyword) ||
          (user.department || "").toLowerCase().includes(keyword) ||
          (user.role || user.position || "").toLowerCase().includes(keyword)
        );
        const approvers = filtered.map(user => ({
          id: user.id,
          name: user.name || user.userName,
          department: user.department || "未設定",
          role: user.role || user.position || "一般"
        }));
        renderApprovers(approvers);
      }
    });
  });

  // ステップ操作のイベントデリゲーション
  container.addEventListener("click", (e) => {
    // ステップ削除
    const deleteBtn = e.target.closest(".delete-step-btn");
    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.index);
      if (confirm("このステップを削除しますか？")) {
        currentSteps.splice(index, 1);
        // ステップ順序を再調整
        currentSteps.forEach((step, i) => {
          step.stepOrder = i + 1;
        });
        renderSteps();
      }
      return;
    }

    // ステップ編集
    const editBtn = e.target.closest(".edit-step-btn");
    if (editBtn) {
      editingStepIndex = parseInt(editBtn.dataset.index);
      container.querySelector("#approver-modal").style.display = "block";
      return;
    }

    // ステップ順序変更（上へ）
    const moveUpBtn = e.target.closest(".move-up-btn");
    if (moveUpBtn) {
      const index = parseInt(moveUpBtn.dataset.index);
      if (index > 0) {
        [currentSteps[index], currentSteps[index - 1]] = [currentSteps[index - 1], currentSteps[index]];
        currentSteps.forEach((step, i) => {
          step.stepOrder = i + 1;
        });
        renderSteps();
      }
      return;
    }

    // ステップ順序変更（下へ）
    const moveDownBtn = e.target.closest(".move-down-btn");
    if (moveDownBtn) {
      const index = parseInt(moveDownBtn.dataset.index);
      if (index < currentSteps.length - 1) {
        [currentSteps[index], currentSteps[index + 1]] = [currentSteps[index + 1], currentSteps[index]];
        currentSteps.forEach((step, i) => {
          step.stepOrder = i + 1;
        });
        renderSteps();
      }
      return;
    }
  });

  // チェックボックス変更
  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("required-checkbox")) {
      const index = parseInt(e.target.dataset.index);
      currentSteps[index].required = e.target.checked;
    }

    if (e.target.classList.contains("parallel-checkbox")) {
      const index = parseInt(e.target.dataset.index);
      currentSteps[index].parallel = e.target.checked;
    }
  });

  // 保存ボタン
  container.querySelector("#save-btn").addEventListener("click", async () => {
    const documentType = container.querySelector("#document-type").value;
    const routeName = container.querySelector("#route-name").value;
    const approvalDeadline = container.querySelector("#approval-deadline").value;
    const parallelApproval = container.querySelector("#parallel-approval").checked;
    const proxyApproval = container.querySelector("#proxy-approval").checked;
    const requiredApproval = container.querySelector('input[name="required-approval"]:checked')?.value;
    const escalationCondition = container.querySelector("#escalation-condition").value;
    const escalationTarget = container.querySelector("#escalation-target").value;
    const notificationMethod = container.querySelector("#notification-method").value;

    if (!documentType || !routeName) {
      alert("文書種別と処理ルート名は必須です");
      return;
    }

    if (currentSteps.length === 0) {
      alert("承認ステップを1つ以上追加してください");
      return;
    }

    // 承認フロー定義を保存
    const flowData = {
      documentTypeId: documentType,
      approvalFlowName: routeName,
      approvalStepNumber: 1,
      approverId: currentSteps[0].approverId,
      approverRole: currentSteps[0].approverRole,
      requiredApprovalFlag: requiredApproval === "all",
      parallelApprovalFlag: parallelApproval,
      approvalDeadlineDays: parseInt(approvalDeadline) || 3,
      escalationTargetId: escalationTarget,
      validStartDate: new Date().toISOString(),
      remarks: `並列承認:${parallelApproval}, 代理承認:${proxyApproval}, 通知方法:${notificationMethod}`,
      creatorId: "current-user-id"
    };

    const saved = await window.aivicApi.save(3, flowData);
    if (saved) {
      // 各承認ステップを保存
      for (let i = 0; i < currentSteps.length; i++) {
        const step = currentSteps[i];
        const stepData = {
          approvalFlowDefinitionId: saved.id,
          stepNumber: step.stepOrder,
          approverId: step.approverId,
          approvalStatus: "未承認",
          requiredFlag: step.required,
          parallelApprovalGroup: step.parallel ? `group-${step.stepOrder}` : null,
          creatorId: "current-user-id"
        };
        await window.aivicApi.save(4, stepData);
      }

      alert("処理ルートを保存しました");

      // フォームクリア
      container.querySelector("#document-type").value = "";
      container.querySelector("#route-name").value = "";
      container.querySelector("#approval-deadline").value = "";
      container.querySelector("#parallel-approval").checked = false;
      container.querySelector("#proxy-approval").checked = false;
      container.querySelector("#escalation-condition").value = "";
      container.querySelector("#escalation-target").value = "";
      container.querySelector("#notification-method").value = "";
      currentSteps = [];
      renderSteps();
    }
  });

  // クリアボタン
  container.querySelector("#clear-btn").addEventListener("click", () => {
    if (confirm("入力内容をクリアしますか？")) {
      container.querySelector("#document-type").value = "";
      container.querySelector("#route-name").value = "";
      container.querySelector("#approval-deadline").value = "";
      container.querySelector("#parallel-approval").checked = false;
      container.querySelector("#proxy-approval").checked = false;
      container.querySelector("#escalation-condition").value = "";
      container.querySelector("#escalation-target").value = "";
      container.querySelector("#notification-method").value = "";
      currentSteps = [];
      renderSteps();
    }
  });

  // プレビューボタン
  container.querySelector("#preview-btn").addEventListener("click", () => {
    if (currentSteps.length === 0) {
      alert("承認ステップを追加してからプレビューしてください");
      return;
    }

    const routeName = container.querySelector("#route-name").value || "未設定";
    const previewText = `処理ルート: ${routeName}\n承認ステップ数: ${currentSteps.length}\n\n` +
      currentSteps.map((step, i) => 
        `${i + 1}. ${step.approverName} (${step.approverRole}) ${step.required ? '[必須]' : '[任意]'} ${step.parallel ? '[並列]' : ''}`
      ).join('\n');

    alert(previewText);
  });

  // 初期描画
  renderSteps();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#document-tbody");
  const resultCount = container.querySelector("#result-count");
  const advancedSearch = container.querySelector("#advanced-search");
  let allDocuments = [];
  let isAdvancedVisible = false;

  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusBadge = getStatusBadge(r.承認状態 || '');
      const urgencyBadge = (r.緊急フラグ === true || r.緊急フラグ === 'true') ? 
        '<span style="background: #ff4444; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px;">緊急</span>' : 
        '<span style="background: rgba(255,255,255,0.1); color: var(--text-muted); padding: 2px 6px; border-radius: 4px; font-size: 11px;">通常</span>';

      return `<tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${r.id ? r.id.substring(0, 8) : ''}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${r.申請種別 || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${r.申請タイトル || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${r.申請者名 || ''}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${statusBadge}</td>
        <td style="padding: 6px 10px; font-size: 12px; color: var(--text);">${formatDate(r.作成日時)}</td>
        <td style="padding: 6px 10px; font-size: 12px;">${urgencyBadge}</td>
        <td style="padding: 6px 10px; font-size: 12px;">
          <button class="action-btn secondary view-btn" data-id="${r.id}" style="margin-right: 4px;">詳細</button>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">編集</button>
        </td>
      </tr>`;
    }).join("");

    resultCount.textContent = `${rows.length}件`;
  }

  function getStatusBadge(status) {
    const statusColors = {
      '申請中': { bg: '#ff9500', color: '#fff' },
      '承認済': { bg: '#00c851', color: '#fff' },
      '却下': { bg: '#ff4444', color: '#fff' },
      '取下げ': { bg: '#666', color: '#fff' }
    };
    const colors = statusColors[status] || { bg: 'rgba(255,255,255,0.1)', color: 'var(--text-muted)' };
    return `<span style="background: ${colors.bg}; color: ${colors.color}; padding: 2px 6px; border-radius: 4px; font-size: 11px;">${status}</span>`;
  }

  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  // 2. 初期データを即座に描画
  if (tables[0] && tables[0].records) {
    allDocuments = tables[0].records;
    renderRows(allDocuments);
  }

  // 最新データを取得
  window.aivicApi.list(0).then(rows => {
    if (rows) {
      allDocuments = rows;
      renderRows(rows);
    }
  });

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-keyword").value.toLowerCase();
    const docType = container.querySelector("#select-doc-type").value;
    const applicant = container.querySelector("#input-applicant").value.toLowerCase();
    const dateFrom = container.querySelector("#input-date-from").value;
    const dateTo = container.querySelector("#input-date-to").value;
    const approvalDateFrom = container.querySelector("#input-approval-date-from").value;
    const approvalDateTo = container.querySelector("#input-approval-date-to").value;
    const approver = container.querySelector("#select-approver").value;
    const department = container.querySelector("#select-department").value;
    const urgency = container.querySelector('input[name="urgency"]:checked').value;

    // チェックボックスの状態を取得
    const statusFilters = [];
    if (container.querySelector("#status-pending").checked) statusFilters.push("申請中");
    if (container.querySelector("#status-approved").checked) statusFilters.push("承認済");
    if (container.querySelector("#status-rejected").checked) statusFilters.push("却下");

    const filtered = allDocuments.filter(doc => {
      // キーワード検索
      if (keyword && !JSON.stringify(doc).toLowerCase().includes(keyword)) return false;

      // 文書種別
      if (docType && doc.申請種別 !== docType) return false;

      // 申請者名
      if (applicant && !(doc.申請者名 || '').toLowerCase().includes(applicant)) return false;

      // 承認状態
      if (statusFilters.length > 0 && !statusFilters.includes(doc.承認状態)) return false;

      // 申請日範囲
      if (dateFrom || dateTo) {
        const docDate = new Date(doc.作成日時);
        if (dateFrom && docDate < new Date(dateFrom)) return false;
        if (dateTo && docDate > new Date(dateTo + 'T23:59:59')) return false;
      }

      // 承認完了日範囲
      if (approvalDateFrom || approvalDateTo) {
        if (!doc.最終承認日時) return false;
        const approvalDate = new Date(doc.最終承認日時);
        if (approvalDateFrom && approvalDate < new Date(approvalDateFrom)) return false;
        if (approvalDateTo && approvalDate > new Date(approvalDateTo + 'T23:59:59')) return false;
      }

      // 承認者
      if (approver && doc.最終承認者名 !== approver) return false;

      // 部署
      if (department && doc.申請者部署 !== department) return false;

      // 緊急度
      if (urgency === '緊急' && !(doc.緊急フラグ === true || doc.緊急フラグ === 'true')) return false;
      if (urgency === '通常' && (doc.緊急フラグ === true || doc.緊急フラグ === 'true')) return false;

      return true;
    });

    renderRows(filtered);
  });

  // 条件クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#input-keyword").value = '';
    container.querySelector("#select-doc-type").value = '';
    container.querySelector("#input-applicant").value = '';
    container.querySelector("#input-date-from").value = '';
    container.querySelector("#input-date-to").value = '';
    container.querySelector("#input-approval-date-from").value = '';
    container.querySelector("#input-approval-date-to").value = '';
    container.querySelector("#select-approver").value = '';
    container.querySelector("#select-department").value = '';
    container.querySelector("#status-pending").checked = false;
    container.querySelector("#status-approved").checked = false;
    container.querySelector("#status-rejected").checked = false;
    container.querySelector('input[name="urgency"][value=""]').checked = true;

    renderRows(allDocuments);
  });

  // 詳細検索展開ボタン
  container.querySelector("#btn-toggle-advanced").addEventListener("click", () => {
    isAdvancedVisible = !isAdvancedVisible;
    advancedSearch.style.display = isAdvancedVisible ? 'block' : 'none';
    container.querySelector("#btn-toggle-advanced").textContent = isAdvancedVisible ? '詳細検索を閉じる' : '詳細検索';
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", () => {
    const headers = ['申請書類ID', '申請種別', '申請タイトル', '申請者名', '承認状態', '申請日', '緊急フラグ'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...allDocuments.map(doc => [
        `"${doc.id || ''}"`,
        `"${doc.申請種別 || ''}"`,
        `"${doc.申請タイトル || ''}"`,
        `"${doc.申請者名 || ''}"`,
        `"${doc.承認状態 || ''}"`,
        `"${formatDate(doc.作成日時)}"`,
        `"${(doc.緊急フラグ === true || doc.緊急フラグ === 'true') ? '緊急' : '通常'}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `電子文書検索結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 5. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async e => {
    const viewBtn = e.target.closest(".view-btn");
    const editBtn = e.target.closest(".edit-btn");

    if (viewBtn) {
      const docId = viewBtn.dataset.id;
      window.showScreen("scr-1779349647621"); // 申請書類確認画面
    }

    if (editBtn) {
      const docId = editBtn.dataset.id;
      window.showScreen("scr-1779346840879"); // 申請書類作成画面
    }
  });
}
